import os,lzma,sys,re
sys.path.insert(0,'/tmp'); from probe import run
os.chdir('/tmp/tlz')
data=open('/usr/lib/python3.10/argparse.py','rb').read()
open('f.bin','wb').write(data)
for mx in ['1','3','5','7','9']:
    if os.path.exists('f.7z'): os.remove('f.7z')
    run(['a','-mx'+mx,'f.7z','f.bin'])
    arc=open('f.7z','rb').read()
    r2=run(['l','-slt','f.7z']); ps=int(re.search(r'Packed Size = (\d+)',r2.stdout).group(1))
    orig=arc[32:32+ps]
    print(f"mx{mx} origlen {ps}")
    best=[]
    for mode_name,mode in [('fast',lzma.MODE_FAST),('norm',lzma.MODE_NORMAL)]:
        for mf_name,mf in [('hc3',lzma.MF_HC3),('hc4',lzma.MF_HC4),('bt2',lzma.MF_BT2),('bt3',lzma.MF_BT3),('bt4',lzma.MF_BT4),('bt5',lzma.MF_BT5)]:
            for nice in [4,8,16,32,64,128,192,273]:
                for depth in [0,4,8,16,32,64,1000]:
                    try:
                        f=[{"id":lzma.FILTER_LZMA2,"dict_size":131072,"lc":3,"lp":0,"pb":2,"mode":mode,"nice_len":nice,"mf":mf,"depth":depth}]
                        c=lzma.compress(data,format=lzma.FORMAT_RAW,filters=f)
                    except Exception as e: continue
                    if c==orig: print(" EXACT",mode_name,mf_name,nice,depth)
                    best.append((abs(len(c)-ps),len(c),mode_name,mf_name,nice,depth, c[:50]==orig[:50]))
    best.sort()
    for b in best[:5]: print(" best",b)
PY
cat /tmp/log_lz2.txt"}

