{"command":"python3 - << 'PY'
import zlib, itertools
def crc(b): return zlib.crc32(b)&0xffffffff
target=0xABAE6403
names=['e1','e2']
encs={'utf8':'utf-8','utf16le':'utf-16le','utf16be':'utf-16be'}
variants={}
for en,enc in encs.items():
  for suffix in ['', '\0','\n','/', ' ']:
    for prefix in ['','\0']:
      s=sum(crc((prefix+n+suffix).encode(enc)) for n in names)
      variants[f"{en} pre={prefix!r} suf={suffix!r}"]=s
  # also uppercase?
for k,v in variants.items():
    print(k,"%08X"% (v&0xffffffff), v>>32, v==target)
# also maybe name is hashed with size? or name bytes are UTF16 with uppercase? try upper
for en,enc in encs.items():
  for tr in [str.upper, str.lower]:
    s=sum(crc(tr(n).encode(enc)) for n in names); print(en,tr,"%08X"%s)
# try hashing data then name empty data same
# Try name converted with backslash? e1 unchanged
# Maybe per-file combined is not CRC(input) but CRC(name) + CRC(data) ??? Then sum = ...
print("crc names utf8 sum already")
# try including newline CRLF etc
for suffix in [b'\r\n',b'\x00\x00',b'  ',b'\n\n']:
  s=sum(crc(n.encode()+suffix) for n in names); print(suffix,"%08X"%s)
  s=sum(crc(n.encode('utf-16le')+suffix) for n in names); print('16',suffix,"%08X"%s)
PY"}

