import zlib
def c(b): return zlib.crc32(b)&0xffffffff
def solve_prefix(target, suffix, n=4):
    base=c(b'\x00'*n+suffix)
    cols=[]
    for i in range(n*8):
        inp=bytearray(b'\x00'*n); inp[i//8]|=(1<<(i%8))
        cols.append(c(bytes(inp)+suffix)^base)
    rhs=target^base
    # gaussian elimination GF2: variables x_i, sum x_i*cols_i = rhs (as 32-bit vectors)
    # Build matrix rows 32 eq
    rows=[]
    for bit in range(32):
        row=0
        for i,col in enumerate(cols):
            if (col>>bit)&1: row|=(1<<i)
        const=(rhs>>bit)&1
        rows.append([row,const])
    piv=[]
    r=0
    where=[-1]*(n*8)
    for col in range(n*8):
        # find pivot row >=r with bit col
        sel=-1
        for i in range(r,32):
            if (rows[i][0]>>col)&1: sel=i; break
        if sel==-1: continue
        rows[r],rows[sel]=rows[sel],rows[r]; where[col]=r
        for i in range(32):
            if i!=r and ((rows[i][0]>>col)&1):
                rows[i][0]^=rows[r][0]; rows[i][1]^=rows[r][1]
        r+=1
    sol=bytearray(n)
    for i in range(n*8):
        if where[i]!=-1 and rows[where[i]][1]: sol[i//8]|=(1<<(i%8))
    return bytes(sol)
