import struct
MASK=0xFFFFFFFFFFFFFFFF
P1=11400714785074694791; P2=14029467366897019727; P3=1609587929392839161; P4=9650029242287828579; P5=2870177450012600261
def rol(x,r): return ((x<<r)|(x>>(64-r)))&MASK
def rnd(acc, inp):
    acc=(acc+inp*P2)&MASK; acc=rol(acc,31); acc=(acc*P1)&MASK; return acc
def xxh64(data,seed=0):
    n=len(data); p=0
    if n>=32:
        v1=(seed+P1+P2)&MASK; v2=(seed+P2)&MASK; v3=seed&MASK; v4=(seed-P1)&MASK
        while p+32<=n:
            v1=rnd(v1, struct.unpack_from('<Q',data,p)[0]); v2=rnd(v2, struct.unpack_from('<Q',data,p+8)[0]); v3=rnd(v3, struct.unpack_from('<Q',data,p+16)[0]); v4=rnd(v4, struct.unpack_from('<Q',data,p+24)[0]); p+=32
        h=(rol(v1,1)+rol(v2,7)+rol(v3,12)+rol(v4,18))&MASK
        for v in (v1,v2,v3,v4):
            v=rnd(0,v); h ^= v; h=(h*P1+P4)&MASK
    else:
        h=(seed+P5)&MASK
    h=(h+n)&MASK
    while p+8<=n:
        k=rnd(0, struct.unpack_from('<Q',data,p)[0]); h ^= k; h=(rol(h,27)*P1+P4)&MASK; p+=8
    if p+4<=n:
        h ^= (struct.unpack_from('<I',data,p)[0]*P1)&MASK; h=(rol(h,23)*P2+P3)&MASK; p+=4
    while p<n:
        h ^= (data[p]*P5)&MASK; h=rol(h,11)*P1&MASK; p+=1
    h ^= h>>33; h=h*P2&MASK; h ^= h>>29; h=h*P3&MASK; h ^= h>>32
    return h
