import os, sys, time, zlib, struct, hashlib, math

MASK64=0xFFFFFFFFFFFFFFFF

# ---------- CRC64 (CRC-64/XZ, reflected ECMA) ----------
_CRC64_POLY=0xC96C5795D7870F42
_crc64_tab=[]
for _i in range(256):
    _c=_i
    for _ in range(8):
        _c=(_c>>1)^(_CRC64_POLY if _c&1 else 0)
    _crc64_tab.append(_c)
def crc64(data, crc=0):
    # crc is previous final value; internal init xor
    c = crc ^ MASK64
    tab=_crc64_tab
    for b in data:
        c = tab[(c ^ b) & 0xFF] ^ (c >> 8)
    return c ^ MASK64

class CRC64:
    def __init__(self): self.v=0
    def update(self,d): self.v=crc64(d,self.v)
    def digest_int(self): return self.v

