    if n>=32:
        v1=(seed+_P1+_P2)&MASK64; v2=(seed+_P2)&MASK64; v3=seed&MASK64; v4=(seed-_P1)&MASK64
        while p+32<=n:
            v1=_xxrnd(v1, struct.unpack_from('<Q',data,p)[0])
            v2=_xxrnd(v2, struct.unpack_from('<Q',data,p+8)[0])
            v3=_xxrnd(v3, struct.unpack_from('<Q',data,p+16)[0])
            v4=_xxrnd(v4, struct.unpack_from('<Q',data,p+24)[0]); p+=32
        h=(_rol64(v1,1)+_rol64(v2,7)+_rol64(v3,12)+_rol64(v4,18))&MASK64
        for v in (v1,v2,v3,v4):
