    else:
        h=(seed+_P5)&MASK64
    h=(h+n)&MASK64
    while p+8<=n:
        h ^= _xxrnd(0, struct.unpack_from('<Q',data,p)[0]); h=(_rol64(h,27)*_P1+_P4)&MASK64; p+=8
    if p+4<=n:
