    return h

class XXH64:
    # streaming implementation: buffer all (files in tests are modest)
    def __init__(self): self.buf=bytearray()
    def update(self,d): self.buf += d
    def digest_int(self): return xxh64(bytes(self.buf))

# Hash objects wrapper
class Hasher:
    # name canonical upper: CRC32, CRC64, SHA1, SHA256, XXH64
    def __init__(self,name):
        self.name=name
        if name=='CRC32': self._v=0
        elif name=='CRC64': self._o=CRC64()
        elif name=='XXH64': self._o=XXH64()
        elif name=='SHA1': self._o=hashlib.sha1()
        elif name=='SHA256': self._o=hashlib.sha256()
        else: raise ValueError(name)
    def update(self,d):
        if self.name=='CRC32': self._v=zlib.crc32(d,self._v)&0xFFFFFFFF
        else: self._o.update(d)
    def digest_bytes_internal(self):
        # bytes in internal (sum) order
        if self.name=='CRC32': return struct.pack('<I',self._v)
        if self.name=='CRC64': return struct.pack('<Q',self._o.digest_int())
        if self.name=='XXH64': return struct.pack('<Q',self._o.digest_int())
        return self._o.digest()
    def digest_text(self):
        return format_digest(self.name, self.digest_bytes_internal())
    def copy(self):
        import copy
        return copy.deepcopy(self)

def format_digest(name, internal_bytes):
    if name=='CRC32': return "%08X" % int.from_bytes(internal_bytes[:4].ljust(4,b'\0'),'little')
    if name in ('CRC64','XXH64'): return "%016X" % int.from_bytes(internal_bytes[:8].ljust(8,b'\0'),'little')
    # SHA lowercase hex of bytes in order
    return internal_bytes.hex()

DIGEST_SIZES={'CRC32':4,'CRC64':8,'SHA1':20,'SHA256':32,'XXH64':8}
HASH_DISPLAY_WIDTH={'CRC32':8,'CRC64':16,'SHA1':40,'SHA256':64,'XXH64':16}

class DigestSum:
    def __init__(self,name):
        self.name=name; self.total=0; self.count=0
    def add_digest_internal(self,b):
        self.total += int.from_bytes(b,'little'); self.count += 1
    def add_hasher(self,h): self.add_digest_internal(h.digest_bytes_internal())
    def text(self):
        size=DIGEST_SIZES[self.name]
        low=self.total & ((1<<(8*size))-1)
        high=self.total >> (8*size)
        lowb=low.to_bytes(size,'little')
        s=format_digest(self.name, lowb)
        if self.count != 1:
