_libcrypto=None
def _load_crypto():
    global _libcrypto
    if _libcrypto is not None: return _libcrypto
    import ctypes
    for name in ('libcrypto.so.3','libcrypto.so'):
        try:
            _libcrypto=ctypes.CDLL(name); return _libcrypto
        except Exception:
            pass
    raise RuntimeError('libcrypto not available')

def aes_ecb_encrypt_blocks(key, data):
    # data multiple of 16
    import ctypes
    lib=_load_crypto()
    ctx=lib.EVP_CIPHER_CTX_new()
    cipher={16:lib.EVP_aes_128_ecb,24:lib.EVP_aes_192_ecb,32:lib.EVP_aes_256_ecb}[len(key)]()
    lib.EVP_EncryptInit_ex(ctx,cipher,None,key,None)
    lib.EVP_CIPHER_CTX_set_padding(ctx,0)
    out=ctypes.create_string_buffer(len(data)+16); outl=ctypes.c_int(0); finl=ctypes.c_int(0)
    lib.EVP_EncryptUpdate(ctx,out,ctypes.byref(outl),data,len(data))
    lib.EVP_EncryptFinal_ex(ctx,ctypes.byref(out,outl.value),ctypes.byref(finl))
    lib.EVP_CIPHER_CTX_free(ctx)
    return out.raw[:outl.value+finl.value]

def _evp_crypt(key, iv, data, encrypt, cipher_name):
    import ctypes
    lib=_load_crypto()
    ctx=lib.EVP_CIPHER_CTX_new()
    fn=getattr(lib, cipher_name)
    cipher=fn()
    if encrypt: lib.EVP_EncryptInit_ex(ctx,cipher,None,key,iv)
    else: lib.EVP_DecryptInit_ex(ctx,cipher,None,key,iv)
    lib.EVP_CIPHER_CTX_set_padding(ctx,0)
    out=ctypes.create_string_buffer(len(data)+32); outl=ctypes.c_int(0); finl=ctypes.c_int(0)
    if encrypt:
        lib.EVP_EncryptUpdate(ctx,out,ctypes.byref(outl),data,len(data))
        lib.EVP_EncryptFinal_ex(ctx,ctypes.byref(out,outl.value),ctypes.byref(finl))
    else:
        lib.EVP_DecryptUpdate(ctx,out,ctypes.byref(outl),data,len(data))
        lib.EVP_DecryptFinal_ex(ctx,ctypes.byref(out,outl.value),ctypes.byref(finl))
    lib.EVP_CIPHER_CTX_free(ctx)
    return out.raw[:outl.value+finl.value]

