    try:
        t=time.localtime(unix_sec)
        return (t.tm_year,t.tm_mon,t.tm_mday,t.tm_hour,t.tm_min,t.tm_sec)
    except Exception:
        # fallback UTC via datetime
        import datetime
        try:
            d=datetime.datetime.utcfromtimestamp(unix_sec)
