    parts=[]
    if folders:
        parts.append(f"{folders} folder" if folders==1 else f"{folders} folders")
    parts.append(f"{files} file" if files==1 else f"{files} files")
    if size_known:
        parts.append(size_descr(size))
    return ", ".join(parts)

def mode_string(mode):
    if mode is None: return ''
    t=(mode>>12)&0xF
    tmap={1:'p',2:'c',4:'d',6:'b',8:'-',10:'l',12:'s'}
    tc=tmap.get(t, "%X"%t)
    s=tc
    # user
    s += 'r' if mode&0o400 else '-'
    s += 'w' if mode&0o200 else '-'
    if mode&0o4000: s += 's' if mode&0o100 else 'S'
    else: s += 'x' if mode&0o100 else '-'
    s += 'r' if mode&0o040 else '-'
    s += 'w' if mode&0o020 else '-'
    if mode&0o2000: s += 's' if mode&0o010 else 'S'
    else: s += 'x' if mode&0o010 else '-'
    s += 'r' if mode&0o004 else '-'
    s += 'w' if mode&0o002 else '-'
    if mode&0o1000: s += 't' if mode&0o001 else 'T'
    else: s += 'x' if mode&0o001 else '-'
    return s

