def format_attributes(attr):
    if attr is None: return ''
    orig=attr
    mode_part=None
    work=attr
    if attr & 0x8000:
        mode=(attr>>16)&0xFFFF
        mode_part=mode_string(mode)
        if ((mode>>12)&0xF)!=0:
            # recognized mode: clear marker and high word
            work = attr & ~0xFFFF8000 & 0xFFFFFFFF
    letters=''; rem=work
    for bit in range(32):
        if work & (1<<bit):
            ch=_ATTR_LETTERS.get(bit)
            if ch is not None:
                letters+=ch; rem &= ~(1<<bit)
    out=letters
    if rem:
        out += " %08X"%rem
    if mode_part is not None:
        out += " "+mode_part
    return out

