    # 5 chars D R H S A
    if attr is None:
        return 'D....' if is_dir else '.....'
    c=['.']*5
    if attr & 0x10: c[0]='D'
    if attr & 0x01: c[1]='R'
    if attr & 0x02: c[2]='H'
    if attr & 0x04: c[3]='S'
    if attr & 0x20: c[4]='A'
    return ''.join(c)

def win_attrs_from_stat(st, is_dir):
    # attributes used when scanning local files for 7z
    mode=st.st_mode
    a=0x8000 | (mode<<16)
    if is_dir: a|=0x10
    else: a|=0x20
    if not (mode & 0o200): a|=0x01
    return a

def dos_time_from_unixns(ns):
    if ns is None: return (1980,1,1,0,0,0)
    sec=ns//1000000000
    y,mo,d,h,mi,s=_local_parts(sec)
    if y<1980: return (1980,1,1,0,0,0)
    if y>2107: return (2107,12,31,23,59,58)
    return (y,mo,d,h,mi,s - (s&1))

def unixns_from_dos(tup):
    # DOS time is local time; convert via mktime
    y,mo,d,h,mi,s=tup
    try:
        sec=int(time.mktime((y,mo,d,h,mi,s,0,0,-1)))
    except Exception:
        sec=0
    return sec*1000000000

def errno_text(e):
    if isinstance(e,OSError) and e.errno is not None:
        return f"errno={e.errno} : {os.strerror(e.errno)}"
    return str(e)

def read_file_bytes(path):
    with open(path,'rb') as f: return f.read()

