def read_varint(data,pos):
    if pos>=len(data): raise OpenArchiveError('Unexpected end of archive')
    first=data[pos]; pos+=1
    if first<0x80: return first,pos
    # count leading ones
    mask=0x80; extra=0
    while first & mask:
        extra+=1; mask>>=1
    if pos+extra>len(data): raise OpenArchiveError('Unexpected end of archive')
    val=(first & (mask-1)) if mask else 0
    # additional bytes are big-endian in the remaining bits sequence:
    for i in range(extra):
        val=(val<<8)|data[pos]; pos+=1
    return val,pos

def write_varint(val):
    if val<0x80: return bytes([val])
    # find extra bytes needed
    for extra in range(1,9):
        # bits available: (7-extra) in first + 8*extra ; first byte has leading ones=extra
        maxval=((1<<(7-extra))-1)<<(8*extra) | ((1<<(8*extra))-1) if extra<7 else (1<<64)-1
        if val<=maxval:
            first_prefix=((0xFF << (8-extra)) & 0xFF) if extra<8 else 0xFF
            # leading extra ones: bits: for extra=1 -> 10000000, 2->11000000
            first_prefix = (0xFF00 >> extra) & 0xFF  # 0x80,0xC0...
            # Actually compute: set top 'extra' bits
            first_prefix=0
            for i in range(extra): first_prefix |= (0x80>>i)
            high = val >> (8*extra)
            first = first_prefix | high
            rest=val & ((1<<(8*extra))-1)
            return bytes([first]) + rest.to_bytes(extra,'big')
