def parse_header_bytes(hdr, archive, full_data, opts):
    r=ReaderC(hdr)
    t=r.varint()
    if t!=0x01: raise OpenArchiveError('Headers Error')
    main_si=None; items=[]
    archive_props=[]
    while True:
        t=r.varint()
        if t==0: break
        if t==0x02:
            # ArchiveProperties
            while True:
                pid=r.varint()
                if pid==0: break
                sz=r.varint(); data=r.bytes(sz); archive_props.append((pid,data))
        elif t==0x04:
            main_si=parse_streams_info(r)
        elif t==0x03:
            # AdditionalStreamsInfo - for external folder/name streams; parse and ignore for now
            add_si=parse_streams_info(r); archive.user_additional=add_si
        elif t==0x05:
            items=parse_files_info(r,archive)
        else:
            raise OpenArchiveError('Headers Error')
    archive.items=items
    archive.main_streams=main_si
    archive.archive_props=archive_props
    return main_si

def open_7z(data, path, opts, physical_size=None):
    if len(data)<32 or not data.startswith(MAGIC):
        if len(data)>=6 and data[:6]==MAGIC:
            raise OpenArchiveError('Unexpected end of archive')
        raise OpenArchiveError('Is not archive')
    # version
    major,minor=data[6],data[7]
    start_crc=struct.unpack('<I',data[8:12])[0]
    next_off,next_size,next_crc=struct.unpack('<QQI',data[12:32])
    if zlib.crc32(data[12:32])&0xFFFFFFFF != start_crc:
        raise OpenArchiveError('Headers Error')
    header_start=32+next_off
    header_end=header_start+next_size
    if header_end>len(data):
        raise OpenArchiveError('Unexpected end of archive')
    hdr=data[header_start:header_end]
    if zlib.crc32(hdr)&0xFFFFFFFF != next_crc:
        raise OpenArchiveError('Headers Error')
    archive=Archive7z(); archive.path=path; archive.type_name='7z'; archive.data=data
    archive.physical_size=physical_size if physical_size is not None else len(data)
    # headers size = 32 + next_size
    headers_size=32+next_size
    # Check if encoded header
    if hdr and hdr[0]==0x17:
        # parse streams info for header stream
        r=ReaderC(hdr); tt=r.varint()
        hsi=parse_streams_info(r)
        # decode header stream from packed data at 32+hsi.pack_pos
        # may need password: if coder includes 7zAES and no password, signal need by returning special? use opts callback
        if opts is None: opts={}
        # Prompt handling: if no password and encryption present, caller should provide password via opts['get_password'] callback
        packed=[]
        pos=32+hsi.pack_pos
        for sz in hsi.pack_sizes:
            packed.append(data[pos:pos+sz]); pos+=sz
        try:
            if any(CODER_NAMES.get(c['id'])=='7zAES' for f in hsi.folders for c in f.coders):
                if opts.get('password') is None and opts.get('get_password'):
                    pw=opts['get_password']()
                    if pw is not None: opts['password']=pw
            decoded=b''
            for f in hsi.folders:
                npacked=len(f.packed_indices) if f.packed_indices else 1
                streams=packed[:npacked]; packed=packed[npacked:]
                decoded += decode_folder(f, streams, opts)
        except DataErrorItem as e:
            if e.msg=='__NEED_PASSWORD__':
                # signal encrypted header need password
                err=OpenArchiveError('Headers Error', special='Cannot open encrypted archive. Wrong password?')
                err.need_password=True; raise err
            # wrong password gives CRC/header parse failure below; treat as headers error special
            err=OpenArchiveError('Headers Error', special='Cannot open encrypted archive. Wrong password?')
            raise err
        hdr=decoded
        # decoded header should parse; if wrong password it will fail
        try:
            main_si=parse_header_bytes(hdr,archive,data,opts)
        except Exception:
            err=OpenArchiveError('Headers Error', special='Cannot open encrypted archive. Wrong password?')
            raise err
        # packed data for files is after header stream packed data? MainStreams PackPos is relative to after signature header (32)
        # But when header is encoded, main packed streams are after encoded header streams? In 7z, PackPos in main streams is offset from end of signature header to packed data, which accounts for size of encoded header packed streams.
    else:
        main_si=parse_header_bytes(hdr,archive,data,opts)
    # Fill item details from streams
    fill_items_from_streams(archive, main_si)
    # props
    methods=[]
    solid=False
    if main_si and main_si.folders:
        # archive Method: collect coder method strings in ?? order: from observation, for each folder, coder order in folder reversed? We'll compute per archive.unique
        seen=[]
        for f in main_si.folders:
            # archive header method for BCJ+LZMA2 was "LZMA2:6k BCJ" while item method was "BCJ LZMA2:6k".
            # Folder coders as stored are in decoding order (LZMA2 then BCJ). Archive method appears to list coders in stored order, item in reverse.
            for c in f.coders:
                ms=archive_coder_method(c)
                if ms not in seen: seen.append(ms)
        methods=seen
        if any(cnt>1 for cnt in main_si.sub_num): solid=True
        # solid defined: any folder with more than one file assigned (substreams count>1) OR number of stream files > folders and sub_num computed below
    props=[]
    props.append(('Physical Size',str(archive.physical_size)))
    props.append(('Headers Size',str(headers_size)))
    if methods:
        props.append(('Method',' '.join(methods)))
    solid_val='+' if is_solid(archive,main_si) else '-'
    props.append(('Solid',solid_val))
    props.append(('Blocks',str(len(main_si.folders) if main_si else 0)))
    archive.props=props
    return archive

def archive_coder_method(coder):
    name=CODER_NAMES.get(coder['id'])
    if name=='PPMD': return 'PPMD'
    if name=='Delta': return 'Delta'
    return coder_method_string(coder)

def is_solid(archive,si):
    if not si or not si.folders: return False
    # count files with streams per folder
    # sub_num may be num of unpack streams per folder (= files in folder for solid)
    return any((n or 1)>1 for n in si.sub_num)

def fill_items_from_streams(archive, si):
    items=archive.items
    if si is None:
        for it in items:
            if it.size is None: it.size=0
            if it.packed_size is None: it.packed_size=0
        return
    # assignment: items with is_file_stream (not empty stream) are assigned in order to substreams of folders
    stream_items=[it for it in items if it.is_file_stream]
    # If sub digests sizes alignment: sub_num length may be less than stream items if substream info omitted and we defaulted 1 per folder but there are many files per folder (7z omits SubStreamsInfo when all folders have one file? In solid case SubStreamsInfo present with CRCs to define sizes.)
    # However MainStreams without SubStreams: each folder corresponds to one file.
    # Build tiles:
    idx=0
    packed_pos_list=[]
    # pack streams are shared: each folder consumes len(packed_indices) packed streams in order
    pack_idx=0
    for fi,f in enumerate(si.folders):
        cnt=si.sub_num[fi] if fi < len(si.sub_num) else 1
        # packed size total for folder = sum pack sizes for its packed streams
        npacked=len(f.packed_indices) if f.packed_indices else 1
        f_packed_sizes=si.pack_sizes[pack_idx:pack_idx+npacked]; pack_idx+=npacked
        f_packed_total=sum(f_packed_sizes)
        subsizes=si.sub_sizes[fi] if fi < len(si.sub_sizes) else [f.unpack_size()]
        subdigs=si.sub_digests[fi] if fi < len(si.sub_digests) else [None]*cnt
        method_item=' '.join(coder_method_string(c) for c in reversed(f.coders)) if False else item_method_string(f)
        enc=any(CODER_NAMES.get(c['id']) in ('7zAES','AES256CBC') for c in f.coders)
        for si_idx in range(cnt):
            if idx>=len(stream_items): break
            it=stream_items[idx]; idx+=1
            it.size=subsizes[si_idx] if si_idx < len(subsizes) else 0
            it.packed_size=f_packed_total if si_idx==0 else None
            if si_idx < len(subdigs): it.crc=subdigs[si_idx]
            it.method=method_item; it.block=fi; it.encrypted=enc
            it.user_data['folder_idx']=fi; it.user_data['sub_idx']=si_idx
            it.user_data['folder']=f; it.user_data['packed_sizes']=f_packed_sizes
            # compute offset in unpacked folder data as sum previous sub sizes
            it.user_data['folder_offset']=sum(subsizes[:si_idx])
        # store folder pack offset index start for later
        f._pack_start_idx=pack_idx-npacked
    for it in items:
        if it.size is None: it.size=0
        if not it.is_file_stream:
            it.packed_size=0; it.crc=None; it.method=''; it.block=None
    archive._si=si

def item_method_string(folder):
    # Item method observed: For folder coders stored [AES, LZMA2], item method = "LZMA2:12 7zAES" (stored order reversed? Actually AES first in header, LZMA2 second; item shows LZMA2 then AES = reverse of stored)
    # For BCJ+LZMA2 created with -m0=BCJ -m1=LZMA2: stored order is probably [LZMA2, BCJ] (?) item method "BCJ LZMA2:6k" = reverse of stored.
    # So item = coder strings in reverse stored order.
    strs=[]
    for c in reversed(folder.coders):
        s=coder_method_string(c)
        # For PPMD, item includes params (coder_method_string already does)
        strs.append(s)
    return ' '.join(strs)

def get_archive_item_data(archive, item, opts):
    data=archive.data; si=archive._si
    fi=item.user_data.get('folder_idx')
    if fi is None: return b''
    # decode whole folder (cache in archive)
    cache=getattr(archive,'_folder_cache',None)
    if cache is None:
        archive._folder_cache={}; cache=archive._folder_cache
    if fi not in cache:
        f=si.folders[fi]
        # Determine packed streams offsets: pack_pos is relative to byte after signature header (32)
        # Sum sizes of packed streams before this folder
        # packed streams are assigned sequentially per folder
        start_pack_idx=getattr(f,'_pack_start_idx',0)
        npacked=len(f.packed_indices) if f.packed_indices else 1
        off=32+si.pack_pos+sum(si.pack_sizes[:start_pack_idx])
        streams=[]
        for sz in si.pack_sizes[start_pack_idx:start_pack_idx+npacked]:
            streams.append(data[off:off+sz]); off+=sz
        # password prompting for data
        if item.encrypted and opts is not None and opts.get('password') is None and opts.get('get_password'):
            pw=opts['get_password']()
            if pw is not None: opts['password']=pw
        try:
            out=decode_folder(f, streams, opts or {})
        except DataErrorItem as e:
            if e.msg=='__NEED_PASSWORD__':
                # re-raise as data error in encrypted file
                raise DataErrorItem('Data Error in encrypted file. Wrong password?')
            raise
        cache[fi]=out
    out=cache[fi]
    off=item.user_data.get('folder_offset',0); size=item.size or 0
    return out[off:off+size]

