def decode_folder(folder, packed_streams, opts):
    # Build global stream indices
    # Map input stream global idx -> (coder_idx, local_in_idx)
    in_map=[]; out_map=[]
    for ci,c in enumerate(folder.coders):
        for li in range(c.get('num_in',1)): in_map.append((ci,li))
        for lo in range(c.get('num_out',1)): out_map.append((ci,lo))
    # output sizes per global out idx
    out_sizes_global=folder.unpack_sizes[:]
    # packed mapping: folder.packed_indices indicate which global input streams are packed, in order
    packed_by_in={}
    for pi, gidx in enumerate(folder.packed_indices):
        if pi < len(packed_streams): packed_by_in[gidx]=packed_streams[pi]
    # bind pairs: input gets output
    bound_input_from_output={i:o for i,o in folder.bind_pairs}
    # evaluation recursive per coder
    coder_outputs={}
    visiting=set()
    def eval_coder(ci):
        if ci in coder_outputs: return coder_outputs[ci]
        if ci in visiting: raise DataErrorItem('Data Error')
        visiting.add(ci)
        coder=folder.coders[ci]
        # global input indices for this coder
        g_ins=[g for g,(cc,_) in enumerate(in_map) if cc==ci]
        inputs=[]
        for g in g_ins:
            if g in packed_by_in:
                inputs.append(packed_by_in[g])
            elif g in bound_input_from_output:
                og=bound_input_from_output[g]; oc,oo=out_map[og]
                outputs=eval_coder(oc); inputs.append(outputs[oo])
            else:
                inputs.append(b'')
        g_outs=[g for g,(cc,_) in enumerate(out_map) if cc==ci]
        osizes=[out_sizes_global[g] if g < len(out_sizes_global) else None for g in g_outs]
        outputs=coder_decode(coder, inputs, osizes, opts)
        visiting.remove(ci)
        coder_outputs[ci]=outputs
        return outputs
    # final output is the global output not bound as source for any input
    bound_outs={o for _,o in folder.bind_pairs}
    final_g=None
    for g in range(len(out_map)):
        if g not in bound_outs: final_g=g; break
    if final_g is None: final_g=len(out_map)-1
    fc,fo=out_map[final_g]
    result=eval_coder(fc)[fo]
    exp=folder.unpack_size()
    if len(result)>exp: result=result[:exp]
    return result

