def format_dict_size(n):
    if n==0: return '0'
    if n & (n-1) == 0:
        return str(n.bit_length()-1)
    if n % (1024*1024)==0:
        return f"{n//(1024*1024)}m"
    if n % 1024==0:
        return f"{n//1024}k"
    return str(n)

def lzma2_dict_from_prop(p):
    if p==40: return 0xFFFFFFFF
    if p>40: return 0xFFFFFFFF
    return (2 + (p&1)) << (p//2 + 11)
def lzma2_prop_from_dict(d):
    if d==0xFFFFFFFF: return 40
    for p in range(41):
        if lzma2_dict_from_prop(p)>=d: return p
    return 40

def coder_method_string(coder):
    cid=coder['id']; props=coder.get('props',b'')
    name=CODER_NAMES.get(cid)
    if name is None:
        return cid.hex()
    if name=='LZMA':
        if len(props)>=5:
            ds=struct.unpack('<I',props[1:5])[0]
            return f"LZMA:{format_dict_size(ds)}"
        return 'LZMA'
    if name=='LZMA2':
        if len(props)>=1:
            ds=lzma2_dict_from_prop(props[0])
            return f"LZMA2:{format_dict_size(ds)}"
        return 'LZMA2'
    if name=='Delta':
        if len(props)>=1: return f"Delta:{props[0]+1}"
        return 'Delta'
    if name=='PPMD':
        # item-level may add params; base name
        if len(props)>=5:
            order=props[0]; mem=struct.unpack('<I',props[1:5])[0]
            # mem displayed as mem{log2?} in item method "PPMD:o6:mem17"
            if mem and (mem&(mem-1))==0:
                return f"PPMD:o{order}:mem{mem.bit_length()-1}"
            return f"PPMD:o{order}:mem{mem}"
        return 'PPMD'
    if name=='BZip2':
        return 'BZip2'
    return name

class Folder:
    def __init__(self):
        self.coders=[]; self.bind_pairs=[]; self.packed_indices=[]
        self.unpack_sizes=[]  # per coder output stream(?) flattened in order read
        self.digest=None
        self.total_in=0; self.total_out=0
    def unpack_size(self):
        # last coder's total out size is unpack size of folder (in header, CodersUnpackSize lists for each coder each out stream)
        if not self.unpack_sizes: return 0
        # unpack_sizes ordered by coder, each coders output(s); folder unpack is size of output stream not bound;
        # For simple coders last value works; BCJ2: need find unbound out.
        # Compute indices:
        outs=[]
        idx=0
        for ci,c in enumerate(self.coders):
            for oi in range(c.get('num_out',1)):
                outs.append(self.unpack_sizes[idx] if idx < len(self.unpack_sizes) else 0); idx+=1
        bound_out={bp[1] for bp in self.bind_pairs}
        for i,v in enumerate(outs):
            if i not in bound_out: return v
        return outs[-1]

def parse_folder(r):
    f=Folder()
    num=r.varint()
    total_in=0; total_out=0
    for _ in range(num):
        b=r.byte(); idsize=b&0x0F; has_attr=bool(b&0x20); complex_=bool(b&0x40)
        cid=r.bytes(idsize)
        nin=1; nout=1
        if complex_:
            nin=r.varint(); nout=r.varint()
        props=b''
        if has_attr:
            psz=r.varint(); props=r.bytes(psz)
        f.coders.append({'id':cid,'num_in':nin,'num_out':nout,'props':props})
        total_in+=nin; total_out+=nout
    f.total_in=total_in; f.total_out=total_out
    for _ in range(total_out-1):
        iidx=r.varint(); oidx=r.varint(); f.bind_pairs.append((iidx,oidx))
    num_packed=total_in-(total_out-1)
    if num_packed>1:
        f.packed_indices=[r.varint() for _ in range(num_packed)]
    else:
        # packed stream index is the one input not bound
        bound_in={bp[0] for bp in f.bind_pairs}
        f.packed_indices=[i for i in range(total_in) if i not in bound_in]
    return f

class StreamsInfo:
    def __init__(self):
        self.pack_pos=0; self.pack_sizes=[]; self.pack_digests=[]
        self.folders=[]; self.sub_num=[]; self.sub_sizes=[]; self.sub_digests=[]

def parse_streams_info(r, collections=None):
    si=StreamsInfo()
    while True:
        t=r.varint()
        if t==0: break
        if t==0x06: # PackInfo
            si.pack_pos=r.varint(); num=r.varint()
            while True:
                tt=r.varint()
                if tt==0: break
                if tt==0x09:
                    si.pack_sizes=[r.varint() for _ in range(num)]
                elif tt==0x0A:
                    si.pack_digests=parse_crc_vector(r,num)
                else: raise OpenArchiveError('Headers Error')
        elif t==0x07: # UnpackInfo
            tt=r.varint()
            if tt!=0x0B: raise OpenArchiveError('Headers Error')
            num=r.varint(); ext=r.byte()
            if ext==0:
                si.folders=[parse_folder(r) for _ in range(num)]
            else:
                didx=r.varint()
                # folder data in external stream (encoded header AdditionalStreams) not common
                raise OpenArchiveError('Headers Error')
            tt=r.varint()
            if tt!=0x0C: raise OpenArchiveError('Headers Error')
            for f in si.folders:
                f.unpack_sizes=[]
                for c in f.coders:
                    for _ in range(c.get('num_out',1)):
                        f.unpack_sizes.append(r.varint())
            # optional CRC
            p_save=r.p
            tt=r.varint()
            if tt==0x0A:
                digs=parse_crc_vector(r,num)
                for f,dg in zip(si.folders,digs): f.digest=dg
                tt=r.varint()
            if tt!=0: raise OpenArchiveError('Headers Error')
        elif t==0x08: # SubStreamsInfo
            while True:
                tt=r.varint()
                if tt==0: break
                if tt==0x0D:
                    si.sub_num=[r.varint() for _ in si.folders]
                elif tt==0x09:
                    # sizes for each folder for all but last substream
                    nums=si.sub_num if si.sub_num else [1]*len(si.folders)
                    si.sub_sizes=[]
                    for fi,f in enumerate(si.folders):
                        cnt=nums[fi]
                        szs=[r.varint() for _ in range(max(0,cnt-1))]
                        # last size derived
                        total=f.unpack_size(); last=total-sum(szs); szs.append(last)
                        si.sub_sizes.append(szs)
                elif tt==0x0A:
                    # CRC for substreams of folders where ... total count:
                    if si.sub_num:
                        count=sum(si.sub_num)
                        # Spec: CRC present only for folders with NumUnpackStream !=1? Actually there is nuance:
                        # It stores CRC for each substream for folders that have digest missing or num!=1?
                        # We'll try parse based on file logic below using a heuristic handled by caller: Here parse all-count then map.
                        all_digs=parse_crc_vector(r,count)
                        # partition
                        pos=0; si.sub_digests=[]
                        for cnt in si.sub_num:
                            si.sub_digests.append(all_digs[pos:pos+cnt]); pos+=cnt
                    else:
                        count=len(si.folders)
                        digs=parse_crc_vector(r,count)
                        si.sub_digests=[[d] for d in digs]
                else: raise OpenArchiveError('Headers Error')
        else:
            raise OpenArchiveError('Headers Error')
    # default substreams
    if not si.sub_num: si.sub_num=[1]*len(si.folders)
    if not si.sub_sizes: si.sub_sizes=[[f.unpack_size()] for f in si.folders]
    if not si.sub_digests:
        si.sub_digests=[[f.digest] if f.digest is not None else [None] for f in si.folders]
    return si

def parse_crc_vector(r,num):
    alldef=r.byte()
    if alldef:
        return [struct.unpack('<I',r.bytes(4))[0] for _ in range(num)]
    bits=r.bytes((num+7)//8)
    out=[]
    for i in range(num):
        if bits[i//8] >> (i%8) & 1: out.append(struct.unpack('<I',r.bytes(4))[0])
        else: out.append(None)
    return out

def parse_bit_vector_bytes(data,num):
    out=[]
    for i in range(num):
        out.append(bool(data[i//8] >> (7-(i%8)) & 1) if False else bool(data[i//8] >> (i%8) & 1))
    return out
