def parse_files_info(r, archive):
    num=r.varint()
    items=[Item('') for _ in range(num)]
    empty_stream=[False]*num
    empty_file=[]; anti=[]
    while True:
        t=r.varint()
        if t==0: break
        size=r.varint(); start=r.p
        if t==0x0E:
            b=r.bytes((num+7)//8)
            empty_stream=parse_bit_vector_bytes(b,num)
        elif t==0x0F:
            cnt=sum(empty_stream); b=r.bytes((cnt+7)//8); empty_file=parse_bit_vector_bytes(b,cnt)
        elif t==0x10:
            cnt=sum(empty_stream); b=r.bytes((cnt+7)//8); anti=parse_bit_vector_bytes(b,cnt)
        elif t==0x11:
            ext=r.byte()
            if ext==0:
                rest=r.bytes(size-(r.p-start))
                names=[]
                # UTF16LE null terminated strings
                parts=rest.split(b'\x00\x00')
                # split handling may break if unicode char contains.. use decode and split '\0'
                try:
                    txt=rest.decode('utf-16le')
                except Exception:
                    txt=rest.decode('utf-16le','replace')
                names=txt.split('\x00')
                for i,it in enumerate(items):
                    if i<len(names): it.path=names[i].replace('\\','/')
            else:
                didx=r.varint()
                # external names stream not supported common
                r.p=start+size
        elif t in (0x12,0x13,0x14):
            alldef=r.byte()
            defined=[True]*num
            if not alldef:
                b=r.bytes((num+7)//8); defined=parse_bit_vector_bytes(b,num)
            ext=r.byte()
            if ext==0:
                for i,it in enumerate(items):
                    if defined[i]:
                        ft=struct.unpack('<Q',r.bytes(8))[0]
                        if t==0x14:
                            it.mtime_ns=util.ft_to_unixns(ft) if ft else None; it.frac7=True
                        elif t==0x12: it.created_ns=util.ft_to_unixns(ft) if ft else None
                        else: it.accessed_ns=util.ft_to_unixns(ft) if ft else None
            else:
                r.p=start+size
        elif t==0x15:
            alldef=r.byte(); defined=[True]*num
            if not alldef:
                b=r.bytes((num+7)//8); defined=parse_bit_vector_bytes(b,num)
            ext=r.byte()
            if ext==0:
                for i,it in enumerate(items):
                    if defined[i]: it.attr=struct.unpack('<I',r.bytes(4))[0]
            else: r.p=start+size
        else:
            r.p=start+size
        if r.p != start+size:
            # adjust to declared size for robustness
            r.p=start+size
    # apply empty stream flags
    eidx=0
    for i,it in enumerate(items):
        if empty_stream[i]:
            it.size=0; it.packed_size=0; it.is_file_stream=False
            is_empty_file=empty_file[eidx] if eidx < len(empty_file) else False
            is_anti=anti[eidx] if eidx < len(anti) else False
            it.anti=is_anti
            if not is_empty_file and not is_anti:
                it.is_dir=True
            else:
                it.is_dir=False
            eidx+=1
        # directory detection by attr too
        if it.attr is not None and (it.attr & 0x10):
            it.is_dir=True
        # mode from attr high
        if it.attr is not None and (it.attr & 0x8000):
            it.mode=(it.attr>>16)&0xFFFF
    return items

def get_password_bytes(password):
    if password is None: return None
    if isinstance(password,bytes): return password
    return password

def derive_7zaes_key(password_str, salt, cycles_power):
    # password as unicode string encoded UTF-16LE
    pw=password_str.encode('utf-16le') if isinstance(password_str,str) else password_str
    h=hashlib.sha256()
    # 2^cycles iterations
    for i in range(1<<cycles_power):
        h.update(pw); 
        if salt: h.update(salt)
        h.update(struct.pack('<Q',i))
    return h.digest()

def parse_7zaes_props(props):
    if len(props)<2: raise DataErrorItem('Headers Error')
    b0=props[0]; b1=props[1]
    cycles=b0 & 0x3F
    salt_size=((b0>>7)&1)+(b1>>4)
    iv_size=((b0>>6)&1)+(b1&0x0F)
    salt=props[2:2+salt_size]
    iv=props[2+salt_size:2+salt_size+iv_size]
    iv=iv.ljust(16,b'\0')[:16]
    return cycles,salt,iv

