def write_crc_vector(digests):
    if all(d is not None for d in digests):
        return b'\x01'+b''.join(struct.pack('<I',d) for d in digests)
    bits=bytearray((len(digests)+7)//8)
    for i,d in enumerate(digests):
        if d is not None: bits[i//8] |= (1 << (i%8))
    return b'\x00'+bytes(bits)+b''.join(struct.pack('<I',d) for d in digests if d is not None)

