def compress_lzma2(data, comp):
    # comp: object with dict_size, lc,lp,pb,nice_len,mf,mode,depth
    ds=comp.get('dict_size') or (1<<25)
    filt={'id':lzma.FILTER_LZMA2,'dict_size':ds,'lc':comp.get('lc',3),'lp':comp.get('lp',0),'pb':comp.get('pb',2)}
    # mode/nice/mf
    if comp.get('algo_fast'): filt['mode']=lzma.MODE_FAST
    else: filt['mode']=lzma.MODE_NORMAL
    if comp.get('nice_len'): filt['nice_len']=comp['nice_len']
    if comp.get('mf'): filt['mf']=comp['mf']
    if comp.get('depth') is not None: filt['depth']=comp['depth']
    enc=lzma.compress(data,format=lzma.FORMAT_RAW,filters=[filt])
    return enc

def calc_reduced_dict(req_dict, unpack_size):
    # dictionary steps: values of form (2or3)<< exp, min 4096
    if unpack_size is None: return req_dict
    # smallest step >= unpack_size, but not exceeding req_dict; min 4096
    steps=[]
