import sys,struct,subprocess,os,shutil
sys.path.insert(0,'/workspace/src')
from fmt7z import ReaderC, parse_streams_info
def offsets(path):
 d=open(path,'rb').read(); no,ns,nc=struct.unpack('<QQI',d[12:32]); h=d[32+no:32+no+ns]; r=ReaderC(h); r.varint()
 res=[]
 while True:
  t=r.varint()
  if t==0: break
  if t==4: parse_streams_info(r)
  elif t==5:
   num=r.varint(); res.append(('numfiles',num))
   while True:
    pos=r.p; tt=r.varint()
    if tt==0: break
    sz=r.varint(); start=r.p
    if tt==0x11:
      ext=r.byte(); res.append(('NameDataAt',r.p))
    elif tt in (0x12,0x13,0x14):
      alld=r.byte();
      if not alld: r.bytes((num+7)//8)
      ext=r.byte(); res.append((f'Time{tt:x}DataAt',r.p))
    elif tt==0x15:
      alld=r.byte();
      if not alld: r.bytes((num+7)//8)
      ext=r.byte(); res.append(('AttrDataAt',r.p))
    elif tt==0x19:
      res.append(('DummyAt_size',pos,sz))
    r.p=start+sz
  else: break
 return res
os.chdir('/tmp/thdr')
cases=[['f'],['ff'],['fff'],['dir'],['dir','f'],['f','ff'],['f','ff','fff'],['f','ff','fff','ffff']]
for c in cases[-4:]:
 for name in c:
  if not os.path.exists(name): open(name,'w').write('x')
for c in cases:
 if os.path.exists('o.7z'): os.remove('o.7z')
 subprocess.run(['/workspace/executable','a','-mhc=off','o.7z']+c,capture_output=True)
 print(c, offsets('o.7z'))
PY
python3 /tmp/fioffsets.py"}

