def zstd_decompress(data, out_size=None):
    import ctypes
    lib=None
    for name in ('libzstd.so.1','libzstd.so'):
        try: lib=ctypes.CDLL(name); break
        except: pass
    if not lib: raise DataErrorItem('Unsupported Method')
    lib.ZSTD_getFrameContentSize.restype=ctypes.c_ulonglong
    lib.ZSTD_decompress.restype=ctypes.c_size_t
    lib.ZSTD_isError.restype=ctypes.c_uint
    fsize=lib.ZSTD_getFrameContentSize(data,len(data))
    cap=out_size if out_size else (int(fsize) if fsize not in (0xFFFFFFFFFFFFFFFF,0xFFFFFFFFFFFFFFFE) else max(1024,len(data)*10))
    # streaming if unknown cap insufficient: loop increasing
    for _ in range(8):
        out=ctypes.create_string_buffer(cap); n=lib.ZSTD_decompress(out,cap,data,len(data))
        if not lib.ZSTD_isError(n): return out.raw[:n]
