    exts={
      'gzip':['.tar.gz','.tgz','.tpz','.gzip','.gz'], 'bzip2':['.tar.bz2','.tbz2','.tbz','.bzip2','.bz2'], 'xz':['.tar.xz','.txz','.xz'],
