# Single stream formats
def strip_archive_ext(filename, ftype):
    # Determine default item name from archive filename
    base=os.path.basename(filename)
    low=base.lower()
    # strip known compound/single extension for this type
    exts={
      'gzip':['.tar.gz','.tgz','.tpz','.gzip','.gz'], 'bzip2':['.tar.bz2','.tbz2','.tbz','.bzip2','.bz2'], 'xz':['.tar.xz','.txz','.xz'],
      'lzma':['.lzma'], 'lzma86':['.lzma86'], 'zstd':['.tar.zst','.tzst','.zst'], 'zip':[], '7z':[],
    }.get(ftype,[])
    for e in exts:
        if low.endswith(e):
            # For .tar.gz, item name when no stored name is base without .gz (keeping .tar) for gzip? bzip2/xz default base stripping: .tbz2 => add .tar? Annot.
            stem=base[:-len(e)]
            if e in ('.tgz','.tpz'): return stem+'.tar'
            if e in ('.tbz2','.tbz'): return stem+'.tar'
            if e=='.txz': return stem+'.tar'
            if e=='.tzst': return stem+'.tar'
            if stem: return stem
            return base
    # fallback strip last extension
    if '.' in base:
        return base.rsplit('.',1)[0]
    return base

