import os,struct
from model import Archive,Item,OpenArchiveError
import fmt7z, formats

EXT_MAP={
 '7z':'7z','cab':'Cab','001':'Split','bz2':'bzip2','bzip2':'bzip2','tbz2':'bzip2','tbz':'bzip2','gz':'gzip','gzip':'gzip','tgz':'gzip','tpz':'gzip','apk':'zip',
 'lzma':'lzma','lzma86':'lzma86','tar':'tar','ova':'tar','xz':'xz','txz':'xz','zip':'zip','z01':'zip','zipx':'zip','jar':'zip','xpi':'zip','odt':'zip','ods':'zip','docx':'zip','xlsx':'zip','epub':'zip','ipa':'zip','appx':'zip','zst':'zstd','tzst':'zstd',
 'sha256':'Hash','sha512':'Hash','sha384':'Hash','sha224':'Hash','sha512-224':'Hash','sha512-256':'Hash','sha3-224':'Hash','sha3-256':'Hash','sha3-384':'Hash','sha3-512':'Hash','sha1':'Hash','sha2':'Hash','sha3':'Hash','sha':'Hash','md5':'Hash','blake2s':'Hash','blake2b':'Hash','blake2sp':'Hash','xxh64':'Hash','crc32':'Hash','crc64':'Hash','cksum':'Hash','asc':'Hash',
}
CANON_TYPES=['7z','Cab','Split','bzip2','gzip','lzma','lzma86','tar','xz','zip','zstd','Hash']
def canonical_type(name):
    if name is None: return None
    low=name.lower()
    for t in CANON_TYPES:
        if t.lower()==low: return t
    return None

def type_by_extension(filename):
    base=os.path.basename(filename)
    if '.' not in base: return None
    ext=base.rsplit('.',1)[1].lower()
    # special 001 numeric for split segments >001? 7za only first segment type has ext 001. Other segments .002 not archive itself.
    return EXT_MAP.get(ext)

def try_parse(type_name,data,path,opts,physical_size=None):
    if type_name=='7z': return fmt7z.open_7z(data,path,opts,physical_size)
    if type_name=='zip': return formats.open_zip(data,path,opts,physical_size)
    if type_name=='tar': return formats.open_tar(data,path,opts,physical_size)
    if type_name=='gzip': return formats.open_gzip(data,path,opts,physical_size)
    if type_name=='bzip2': return formats.open_bzip2(data,path,opts,physical_size)
    if type_name=='xz': return formats.open_xz(data,path,opts,physical_size)
    if type_name=='lzma': return formats.open_lzma_alone(data,path,opts,physical_size,False)
    if type_name=='lzma86': return formats.open_lzma_alone(data,path,opts,physical_size,True)
    if type_name=='zstd': return formats.open_zstd(data,path,opts,physical_size)
    if type_name=='Split': return open_split(data,path,opts,physical_size)
    if type_name=='Cab':
        from cab import open_cab; return open_cab(data,path,opts,physical_size)
    if type_name=='Hash':
        from hasharc import open_hash; return open_hash(data,path,opts,physical_size)
    raise OpenArchiveError('Is not archive')

def detect_signature(data):
    if data.startswith(b'7z\xbc\xaf\x27\x1c'): return '7z'
    if data.startswith(b'MSCF'): return 'Cab'
    if data.startswith(b'BZh'): return 'bzip2'
    if data.startswith(b'\x1f\x8b\x08'): return 'gzip'
    if data.startswith(b'\xfd7zXZ\x00'): return 'xz'
    if len(data)>=265 and data[257:262]==b'ustar': return 'tar'
    # tar old v7 w/o magic but header checksum could be detected by parser attempt later
    if data.startswith(b'PK\x03\x04') or data.startswith(b'PK\x05\x06') or data.startswith(b'PK\x06\x06') or data.startswith(b'PK\x07\x08'): return 'zip'
    if len(data)>=4 and struct.unpack_from('<I',data,0)[0]==0xFD2FB528: return 'zstd'
    return None

def open_archive_data(data,path,opts):
    # opts: type_override, excluded_types set lower, password/get_password
    if len(data)==0:
        raise OpenArchiveError(None)
    forced=(opts or {}).get('type_override')
    excluded={(x or '').lower() for x in ((opts or {}).get('excluded_types') or [])}
    if forced:
        ct=canonical_type(forced)
        if ct is None: raise Exception('Unsupported archive type')
        if ct.lower() in excluded: raise OpenArchiveError(None)
        try:
            return try_parse(ct,data,path,opts,len(data))
        except OpenArchiveError as e:
            e.preferred_type=ct; raise
    pref=type_by_extension(path)
    # Split handling by ext .001: needs file path on disk to find volumes - handled at file level
    if pref and pref.lower() not in excluded:
        try:
            return try_parse(pref,data,path,opts,len(data))
        except OpenArchiveError as e:
            # if signature mismatch, try detect other
            if e.reason=='Is not archive':
                sig=detect_signature(data)
                if sig and sig!=pref and sig.lower() not in excluded:
                    try:
                        arc=try_parse(sig,data,path,opts,len(data)); arc.open_warning=f"Open WARNING: Cannot open the file as [{pref}] archive"; arc.warnings_count=1; return arc
                    except OpenArchiveError:
                        pass
            e.preferred_type=pref; raise
    sig=detect_signature(data)
    if sig and sig.lower() not in excluded:
        try: return try_parse(sig,data,path,opts,len(data))
        except OpenArchiveError as e:
            # If extension unknown but sign detected parser gives specific reason, original error probably generic or detailed? Test with corrupt random signature names later. Use preferred=sig for detailed errors except Is not.
            if e.reason and e.reason!='Is not archive':
                e.preferred_type=sig; raise
            raise OpenArchiveError(None)
    # Try tar checksum-based detection for v7
    if 'tar' not in excluded:
        try: return try_parse('tar',data,path,opts,len(data))
        except Exception: pass
    raise OpenArchiveError(None)

def open_split(data,path,opts,physical_size=None):
    # This is only invoked via file-level path where actual bytes may already be concatenated volumes with info in opts
    # opts may carry _split_info dict
    info=(opts or {}).get('_split_info')
    if not info:
        raise OpenArchiveError('Is not archive')
    from model import Archive
    outer=Archive(); outer.path=path; outer.type_name='Split'; outer.data=data; outer.physical_size=info['first_size']; outer.is_split_container=True
    outer.inner_name=info['inner_name']; outer.volumes=info['volumes']; outer.total_physical=info['total_size']
    outer.props=[('Physical Size',str(info['first_size'])),('Volumes',str(info['volumes'])),('Total Physical Size',str(info['total_size']))]
    # open inner using inner_name extension
    inner_opts=dict(opts); inner_opts.pop('_split_info',None)
    # Inner opening should use name for type detection but display path as inner_name
    try:
        inner=open_archive_data(data,info['inner_name'],inner_opts)
    except OpenArchiveError as e:
        # mimic: error refers to inner name/type in details but overall outer? caller formulas use archive file path. Store info.
        e.split_outer=outer; raise
    outer.inner=inner; outer.items=inner.items
    return outer

def open_archive_file(filepath, display_path, opts):
    # Handle split volumes if file ends .001 and not forced to another type (or forced Split/innertype?)
    opts=dict(opts or {})
    base=os.path.basename(filepath)
    is001=False
    if '.' in base:
        ext=base.rsplit('.',1)[1]
        if ext=='001': is001=True
    # forced type "Split" also
    if is001 and canonical_type(opts.get('type_override')) not in ('7z','zip','tar','gzip','bzip2','xz'):
        # gather volumes
        prefix=filepath[:-4]  # remove .001 (keep dot? filepath ends .001 -> remove last 4)
        # inner name = display path without .001
        inner_display=display_path[:-4] if display_path.endswith('.001') else display_path
        volumes=[]; total=0; first_size=None; data_parts=[]
        idx=1
        while True:
            suffix=f".{idx:03d}"
            # For >999, suffix becomes .1000 (4 digits) automatically by f-string width minimum.
            p=prefix+suffix
            if not os.path.exists(p): break
            sz=os.path.getsize(p); volumes.append(p); total+=sz
            if first_size is None: first_size=sz
            with open(p,'rb') as f: data_parts.append(f.read())
            idx+=1
            if idx>10000: break
        if volumes:
            data=b''.join(data_parts)
            opts['_split_info']={'inner_name':inner_display,'volumes':len(volumes),'total_size':total,'first_size':first_size}
            # If forced type is say 7z, handled above not here. If forced Split or none
            return try_parse('Split',data,display_path,opts,first_size)
    with open(filepath,'rb') as f: data=f.read()
    return open_archive_data(data,display_path,opts)

def get_item_data(archive,item,opts):
    if archive.is_split_container and archive.inner is not None:
        return get_item_data(archive.inner,item,opts)
    t=archive.type_name
    if t=='7z': return fmt7z.get_archive_item_data(archive,item,opts)
    if t=='zip': return formats.get_zip_item_data(archive,item,opts)
    if t=='tar': return formats.get_tar_item_data(archive,item,opts)
    if t=='gzip': return formats.get_gzip_data(archive,item,opts)
    if t in ('bzip2','xz','lzma','lzma86','zstd'): return formats.get_single_item_data(archive,item,opts)
    if t=='Cab':
        from cab import get_cab_item_data; return get_cab_item_data(archive,item,opts)
    if t=='Hash':
        from hasharc import get_hash_item_data; return get_hash_item_data(archive,item,opts)
    return b''
