import os,sys,zlib,time,struct,fnmatch,re,stat,shutil
from model import *
import util, fmt7z, formats, openarc

def S(): return STREAMS

def is_wildcard(s):
    return ('*' in s) or ('?' in s)

def seg_match(pattern, name, case_sensitive=True):
    if not case_sensitive:
        pattern=pattern.lower(); name=name.lower()
    # fnmatch supports [] which 7zip may not; translate manually star/question only.
    regex='^'
    for ch in pattern:
        if ch=='*': regex+='.*'
        elif ch=='?': regex+='.'
        else: regex+=re.escape(ch)
    regex+='$'
    return re.match(regex,name,re.DOTALL) is not None

def path_match(pattern,path,case_sensitive=True):
    # Match full archive path by components (segments count exact)
    pparts=pattern.split('/')
    parts=path.split('/')
    if len(pparts)!=len(parts): return False
    return all(seg_match(a,b,case_sensitive) for a,b in zip(pparts,parts))

def archive_pattern_match(pattern,path,opts,is_dir=False):
    case_sensitive=opts.case_sensitive
    pat=pattern.replace('\\','/')
    # Strip leading ./ and trailing /
    if pat.startswith('./'): pat=pat[2:]
    pat_strip=pat.rstrip('/')
    # If pattern with no slash and recursion for archive names (-r mode specified globally for member filters?) handled by caller with alternative patterns.
    if path_match(pat_strip,path,case_sensitive): return True
    # Match ancestor directory (pattern represents directory)
    parts=path.split('/')
    for i in range(1,len(parts)):
        anc='/'.join(parts[:i])
        if path_match(pat_strip,anc,case_sensitive): return True
    return False

def item_selected(item, includes, excludes, opts):
    # includes are NameSpec objects / dicts with pattern, recursive type, etc.
    path=item.path
    def matches(spec):
        pat=spec['pattern'] if isinstance(spec,dict) else spec.pattern
        rec=spec.get('rec') if isinstance(spec,dict) else spec.rec
        # Recursion for archive member names: if rec enabled and pattern has no slash, match basename at any depth
        if rec in ('r','r0') and '/' not in pat:
            if seg_match(pat,path.split('/')[-1],opts.case_sensitive): return True
            if item.is_dir and seg_match(pat,path.split('/')[-1],opts.case_sensitive): return True
            # if pattern names a directory at any depth, ancestors basename match
            for anc in path.split('/')[:-1]:
                if seg_match(pat,anc,opts.case_sensitive): return True
        return archive_pattern_match(pat,path,opts,item.is_dir)
    if includes:
        ok=any(matches(s) for s in includes)
    else: ok=True
    if not ok: return False
    if excludes and any(matches(s) for s in excludes): return False
    return True

