    lines=[]
    if archive.is_split_container:
        lines.append('--')
        lines.append(f"Path = {archive.path}")
        if archive.open_warning: lines.append(archive.open_warning)
        lines.append('Type = Split')
        for k,v in archive.props: lines.append(f"{k} = {v}")
        lines.append('----')
        lines.append(f"Path = {archive.inner_name}")
