def list_table(archive, items, opts, bare=False):
    out=[]
    sep="------------------- ----- ------------ ------------  ------------------------"
    if not bare:
        out.append("   Date      Time    Attr         Size   Compressed  Name")
        out.append(sep)
    total_size=0; size_known=True; total_comp=0; comp_known=True
    folders=0; files=0
    # For 7z total comp grouping by folder
    folder_contrib={}
    for it in items:
        if it.is_dir: folders+=1
        else: files+=1
        date=it.datetime_text_nofrac()
        attr=it.attr_col_override or util.attr_column(it.attr,it.is_dir)
        size_s=f"{it.size:>12}" if it.size is not None else ' '*12
        comp_s=f"{it.packed_size:>12}" if it.packed_size is not None else ' '*12
        out.append(f"{date:<19} {attr} {size_s} {comp_s}  {it.path}")
        if it.size is None: size_known=False
        else: total_size+=it.size
        if archive.type_name=='7z' or (archive.inner and archive.inner.type_name=='7z'):
            fi=it.user_data.get('folder_idx')
            if fi is not None:
                if fi not in folder_contrib:
                    folder_contrib[fi]=(it.packed_size if it.packed_size is not None else archive.physical_size if not archive.is_split_container else archive.total_physical)
            else:
                if it.packed_size is not None: total_comp+=it.packed_size
        else:
            if it.packed_size is not None: total_comp+=it.packed_size
    if folder_contrib: total_comp += sum(folder_contrib.values())
    if hasattr(archive,'total_compressed_override') and archive.total_compressed_override is not None and items:
        # only if all selected? For single-stream formats, one item selected use override; if item filtered out, items empty.
        total_comp=archive.total_compressed_override
    if not bare:
        out.append(sep)
        count=f"{files} files"
        if folders: count+=f", {folders} folders"
        tsize=f"{total_size:>12}" if size_known else ' '*12
        tcomp=f"{total_comp:>12}" if items or size_known else f"{0:>12}"
        # If no items, total comp shows 0
        out.append(f"{max_datetime_text(items):<19} {'':<5} {tsize} {tcomp}  {count}")
    return '\n'.join(out)+'\n', {'folders':folders,'files':files,'size':total_size if size_known else None,'compressed':total_comp}

def slt_item_lines(archive,item,opts):
    # Generate property lines ordered per format.
    t=archive.inner.type_name if archive.is_split_container and archive.inner else archive.type_name
    lines=[]
