            if frac_digits not in (None,0,7):
                base=util.fmt_datetime_from_unixns(ns,frac7=False)
                frac=ns - (ns//10**9)*10**9
                s=str(frac//(10**(9-frac_digits))).rjust(frac_digits,'0') if frac_digits>0 else ''
                return base+('.'+s if frac_digits>0 else '')
            return util.fmt_datetime_from_unixns(ns,frac7=frac7)
        if dos is not None: return util.fmt_datetime_dos(dos,frac7=frac7)
        return ''
    if t=='7z':
        add('Path',item.path)
        add('Size',item.size if item.size is not None else '')
        add('Packed Size',item.packed_size if item.packed_size is not None else '')
        add('Modified',dt(item.mtime_ns,True,item.mtime_dos))
        add('Attributes',util.format_attributes(item.attr) if item.attr is not None else '')
        add('CRC',f"{item.crc:08X}" if item.crc is not None else '')
        add('Encrypted','+' if item.encrypted else '-')
        add('Method',item.method or '')
        add('Block',item.block if item.block is not None else '')
    elif t=='zip':
        add('Path',item.path); add('Folder','+' if item.is_dir else '-'); add('Size',item.size); add('Packed Size',item.packed_size)
        add('Modified',dt(item.mtime_ns,item.frac7,item.mtime_dos))
        add('Created',dt(item.created_ns,True) if item.created_ns else '')
        add('Accessed',dt(item.accessed_ns,True) if item.accessed_ns else '')
        add('Attributes',util.format_attributes(item.attr) if item.attr is not None else '')
        add('Encrypted','+' if item.encrypted else '-'); add('Comment',item.comment or '')
        add('CRC',f"{item.crc:08X}" if item.crc is not None else '')
        add('Method',item.method); add('Characteristics',item.characteristics or ''); add('Host OS',item.host_os); add('Version',item.version_needed); add('Volume Index',item.volume_index); add('Offset',item.offset)
    elif t=='tar':
        add('Path',item.path); add('Folder','+' if item.is_dir else '-'); add('Size',item.size); add('Packed Size',item.packed_size)
        # frac digits for pax mtime stored
        fd=item.user_data.get('frac_digits',0); add('Modified',dt(item.mtime_ns,False,None,fd))
        add('Created',''); add('Accessed',''); add('Mode',util.mode_string(item.mode) if item.mode is not None else '')
        add('User',item.uname or ''); add('Group',item.gname or ''); add('User ID',item.uid if item.uid is not None else ''); add('Group ID',item.gid if item.gid is not None else '')
        add('Symbolic Link',item.symlink or ''); add('Hard Link',item.hardlink or ''); add('Characteristics',item.characteristics or '')
        # Comment: replace newlines/control with '_' as observed printer
        com=item.comment or ''
        com=''.join(ch if ch not in '\n\r\t' else '_' for ch in com)
        add('Comment',com); add('Device Major',item.dev_major if item.dev_major is not None else ''); add('Device Minor',item.dev_minor if item.dev_minor is not None else '')
    elif t=='gzip':
        add('Path',item.path); add('Size',item.size); add('Packed Size',item.packed_size); add('Modified',dt(item.mtime_ns,False,item.mtime_dos)); add('Host OS',item.host_os); add('CRC',f"{item.crc:08X}" if item.crc is not None else '')
    elif t in ('bzip2','lzma','lzma86','zstd'):
        add('Size',item.size if item.size is not None else ''); add('Packed Size',item.packed_size if item.packed_size is not None else '')
    elif t=='xz':
        add('Size',item.size); add('Packed Size',item.packed_size); add('Method',item.method)
    else:
        # generic from slt_extra if present
        add('Path',item.path); add('Size',item.size); add('Packed Size',item.packed_size); add('Modified',dt(item.mtime_ns,item.frac7,item.mtime_dos))
        if item.slt_extra:
            for k,v in item.slt_extra: add(k,v)
    return lines

def list_archive_body(archive,items,opts,bare=False):
    if opts.tech_info:
        out=[]
        if not bare: out.append('----------')
        for idx,it in enumerate(items):
            if idx>0: out.append('')
            out.extend(slt_item_lines(archive,it,opts))
        out.append('')
        return '\n'.join(out)+'\n'
    else:
        txt,stats=list_table(archive,items,opts,bare)
        return txt
