def phase1_parse_switch(token):
    body=token[1:]
    if body=='':
        raise CmdLineError(f"Unknown switch:\n{token}",1)
    low=body.lower()
    chosen=None
    for d in DEFS:
        if low.startswith(d.name):
            chosen=d; break
    if chosen is None:
        raise CmdLineError(f"Unknown switch:\n{token}",1)
    rest=body[len(chosen.name):]
    if chosen.kind=='bool':
        if rest!='': raise CmdLineError(f"Too long switch:\n{token}",1)
    elif chosen.kind=='boolminus':
        if rest not in ('','-'): raise CmdLineError(f"Incorrect switch postfix:\n{token}",1)
    elif chosen.kind=='enum':
        if len(rest)<chosen.minlen: raise CmdLineError(f"Too short switch:\n{token}",1)
        if len(rest)!=1 or rest not in chosen.allowed: raise CmdLineError(f"Incorrect switch postfix:\n{token}",1)
    elif chosen.kind=='enum_opt':
        if rest not in ('','-','0'): raise CmdLineError(f"Incorrect switch postfix:\n{token}",1)
    elif chosen.kind=='numeric':
        if rest!='' and not rest.isdigit(): raise CmdLineError(f"Unsupported switch postfix -{chosen.name}\n{rest}",1)
    elif chosen.kind in ('string','wild'):
        if len(rest)<chosen.minlen: raise CmdLineError(f"Too short switch:\n{token}",1)
    return (chosen.name,rest,token)

