def parse_args(argv):
    opts=Options(); import time; opts.start_time=time.time()
    raw_switches=[]; pos_tokens=[]; stop=False; command=None; has_any_token=False
    # First collect raw arguments with phase1 switch checking in lexical order, but @list expansion for positional names will need command position: if a listfile occurs before command, its lines are names not commands. Original parser probably expands listfiles where file names expected, after command/archive. We expand immediately: if command not seen and token @... it might be treated as ??? For simplicity if no command, @ token is treated as a positional token to become command candidate? It will result unsupported command @.. Let's check original later.
    tokens=[]
    i=0
    # Help special --help tokens are converted to -h switch before generic? If token is --help and not stop, treat as help switch.
    expanded=[]
    list_expansion_done=False
    for token in argv:
        has_any_token=True
        if not stop and token=='--':
            stop=True; expanded.append(('stop',token)); continue
        if not stop and token=='--help':
            raw_switches.append(('h','','-h')); expanded.append(('switch','-h')); continue
        if not stop and token.startswith('-'):
            sw=phase1_parse_switch(token); raw_switches.append(sw); expanded.append(('switch',token)); continue
        if not stop and token.startswith('@') and token!='@':
