            # Expansion is deferred: record marker token; lines inserted as positional tokens in command parsing below.
            expanded.append(('listfile',token[1:])); continue
        expanded.append(('pos',token))
    # determine command and positionals from expanded, expanding listfiles in-place as positions (each line a pos token)
    # Need to know charset from raw switches for listfiles: find last scs switch before? Simplified: use any scs switch in raw_switches.
    list_charset=None
    for name,rest,tok in raw_switches:
        if name=='scs': list_charset=rest
    positionals=[]; listfile_errors=[]
    # We'll need read listfiles; errors are raised after stream setup (?) We'll store and raise later in main after banner/config.
    def lines_for_listfile(path):
        try:
            data=open(path,'rb').read()
        except OSError as e:
            listfile_errors.append((path,e)); return []
        # charset selection
        cs=(list_charset or '').upper()
        if data.startswith(b'\xff\xfe') or cs=='UTF-16LE': text=data.decode('utf-16le','replace').lstrip('\ufeff')
        elif data.startswith(b'\xfe\xff') or cs=='UTF-16BE': text=data.decode('utf-16be','replace').lstrip('\ufeff')
        elif data.startswith(b'\xef\xbb\xbf'): text=data[3:].decode('utf-8','replace')
        elif cs in ('WIN','DOS'): text=data.decode('cp437' if cs=='DOS' else 'cp1252','replace')
        else: text=data.decode('utf-8','replace')
        out=[]
        for line in text.splitlines():
            if line=='': continue
            if len(line)>=2 and line[0]=='"' and line[-1]=='"': line=line[1:-1]
            out.append(line)
        return out
    command=None
    for kind,val in expanded:
        if kind=='switch' or kind=='stop': continue
        items=[]
        if kind=='listfile': items=lines_for_listfile(val)
        else: items=[val]
        for item in items:
            if command is None:
                command=item
            else:
