    opts.command=command.lower() if command else None; opts.cmd_raw=command; opts.positionals=positionals; opts.switches=raw_switches; opts._listfile_errors=listfile_errors; opts._has_any_token=has_any_token
    # Process switches semantic (but streams/bs first handled by caller? we set streams here because banner phase needs them before other errors. However some semantic errors should occur after banner. Configure streams first in caller by scanning raw switches.)
    return opts

def configure_streams(opts):
    for name,rest,tok in opts.switches:
        if name=='bso': STREAMS.so_mode=int(rest)
        elif name=='bse': STREAMS.se_mode=int(rest)
        elif name=='bsp': STREAMS.sp_mode=int(rest)
        elif name=='bd': STREAMS.bd=True
    # bare / so handled in process_switches before banner in main: check raw
    for name,rest,tok in opts.switches:
        if name=='ba': opts.bare=True
        if name=='so': opts.stdout_data=True
    if opts.stdout_data and opts.command in ('e','x'):
        STREAMS.to_stdout_data=True

def process_switches(opts):
    # Called after banner printed (except help check before). Validate semantic values that produce CmdLine errors after banner.
    for name,rest,tok in opts.switches:
        lowrest=rest.lower()
        if name=='h' or name=='?': opts.help=True
        elif name=='y': opts.yes=True
        elif name=='r': opts.recursive='r' if rest=='' else ('r-' if rest=='-' else 'r0')
        elif name=='bb': opts.log_level=int(rest) if rest else 0
        elif name=='bd': opts.disable_progress=True; STREAMS.bd=True
        elif name=='bt': opts.show_time=True
        elif name=='o': opts.output_dir=rest[1:] if rest.startswith('=') else rest
        elif name=='p': opts.password=rest if rest!='' else None; opts.password_specified=True
        elif name=='t': opts.type_override=rest
        elif name=='ao': opts.overwrite_mode=rest
        elif name=='an': opts.disable_archive_name=True
        elif name=='sa': opts.archive_name_mode=rest
        elif name=='scc':
            if rest.upper() not in ('UTF-8','WIN','DOS'):
                raise CmdLineError(f"Unsupported charset:\n{rest.lower()}",2)
            opts.charset_console=rest
        elif name=='scs':
            if not (rest.upper() in ('UTF-8','UTF-16LE','UTF-16BE','WIN','DOS') or rest.isdigit()):
                raise CmdLineError(f"Unsupported charset:\n{rest.lower()}",2)
            opts.charset_list=rest
        elif name=='scrc':
            opts.hash_value_raw=rest
            if rest=='':
                opts.hash_methods=['CRC32']
            elif rest=='*': opts.hash_methods=['CRC32','CRC64','SHA256','SHA1','XXH64']
            else:
                # can be comma? Original accepts one name; invalid handled in hash/open contexts as E_NOTIMPL for h. Keep raw upper.
                opts.hash_methods=[rest.upper()]
        elif name=='sdel': opts.delete_after=True
        elif name=='si': opts.stdin=True; opts.stdin_name=rest
        elif name=='so': opts.stdout_data=True
        elif name=='snh': opts.store_hardlinks=True
        elif name=='snl': opts.store_symlinks=True
        elif name=='sni': opts.store_nt_security=True
        elif name=='sns': opts.store_alt_streams=(rest!='-')
        elif name=='spd': opts.disable_wildcards=True
        elif name=='spe': opts.eliminate_root=True
        elif name=='spf':
            if rest=='': opts.spf_mode=1
            elif rest=='2': opts.spf_mode=2
            else: raise CmdLineError(f"Unsupported -spf:\n{rest}",2)
        elif name=='ssc': opts.case_sensitive=(rest!='-')
        elif name=='sse': opts.stop_on_error=True
        elif name=='ssp': opts.preserve_atime=True
        elif name=='ssw': opts.compress_shared=True
        elif name=='stl': opts.set_arc_timestamp=True
        elif name=='stm': opts.thread_affinity=rest
        elif name=='stx': opts.excluded_types.append(rest)
        elif name=='slt': opts.tech_info=True
        elif name=='slp': opts.large_pages=True
        elif name=='sfx': opts.sfx=rest
        elif name=='seml': opts.email=rest
        elif name=='v': opts.volumes.append(rest)
        elif name=='w': opts.work_dir=rest; opts.work_dir_specified=True
        elif name=='m': opts.method_values.append(rest)
        elif name=='u': opts.update_options_raw.append(rest)
        elif name=='slf': opts.list_fields=rest
        elif name=='shd': opts.shd=rest
        elif name in ('i','x','ai','ax'):
            # parse wildcard specs semantically
            create_wildcard_spec(opts,name,rest)
        elif name=='ba': opts.bare=True
        # other booleans ignored
    # defaults
    if opts.hash_methods is None: opts.hash_methods=['CRC32']
    return opts

def create_wildcard_spec(opts,swname,rest):
    # rest original after switch name; parse prefix modifiers
    val,rec,mmode,no_wc=parse_wildcard_spec_value(rest,opts.recursive)
    # listfile inside switch @file indicated in namespec rest still starts @ after modifiers? parse_wildcard... doesn't strip !/@. Handle:
    # val is after modifier prefix; expected first char in '!@'
    if not val or val[0] not in '!@':
