    marker=val[0]; pat=val[1:]
    dest={'i':opts.include_specs,'x':opts.exclude_specs,'ai':opts.include_archive_specs,'ax':opts.exclude_archive_specs}[swname]
    if marker=='@':
        # list file with each line a pattern (no marker prefix)
        # Read now; errors become phase2 listfile error like positional @ (?) We'll create special error stored.
        try:
            lines=read_listfile(pat)
        except ListFileError as e:
            opts._listfile_errors.append((e.path,e.err)); return
        for line in lines:
            sp=NameSpec(line,rec,mmode,no_wc,orig=line,from_include=True); dest.append(sp)
    else:
        sp=NameSpec(pat,rec,mmode,no_wc,orig=pat,from_include=True); dest.append(sp)

def positional_specs(opts, patterns, include_switch_specs=True):
    specs=[]
    # positional file names are included specs with global recursive setting and default wildcard handling
    for p in patterns:
        sp=NameSpec(p,opts.recursive,None,opts.disable_wildcards,orig=p); specs.append(sp)
    if include_switch_specs:
        specs.extend(opts.include_specs)
    return specs
