    STREAMS.out("\nScan WARNINGS for files and folders:\n\n")
    for display,msg in warnings:
        STREAMS.out(f"{display} : {msg}\n")
    STREAMS.out("----------------\n")
    STREAMS.out(f"Scan WARNINGS: {len(warnings)}\n")

def emit_scan_warning_stderr(warnings):
    for display,msg in warnings:
        STREAMS.err(f"\nWARNING: {msg}\n{display}\n\n")

def open_error_texts(path, err, for_list):
    pref=getattr(err,'preferred_type',None); special=getattr(err,'special',None); reason=getattr(err,'reason',None)
    if pref:
        if for_list:
            return f"\nERROR: {path} : {path}\nOpen ERROR: Cannot open the file as [{pref}] archive\n\n\nERRORS:\n{reason}\n\n"
        else:
            return f"ERROR: {path}\n{path}\nOpen ERROR: Cannot open the file as [{pref}] archive\n\n\nERRORS:\n{reason}\n"
    if special:
        if for_list:
            # If special came from handler selected by extension, err would have pref & reason? In our parser encrypted header with pref not set but reason Headers. Need know whether detail included: open_archive_data sets pref on raise for by-extension, so special+reason+pref? Actually for enc 7z by ext, our open_7z error has special+reason, open_archive_data's pref branch sets e.preferred_type=pref then this branch would treat pref first and generate wrong format. So prioritize special if special is set and pref.
            return f"\nERROR: {path} : {special}\n\nERRORS:\n{reason}\n\n" if reason else f"\nERROR: {path} : {special}\n\n\n"
        else:
            return f"ERROR: {path}\n{special}\n\nERRORS:\n{reason}\n" if reason else f"ERROR: {path}\n{special}\n\n"
    # generic
    if for_list: return f"\nERROR: {path} : Cannot open the file as archive\n\n\n"
    return f"ERROR: {path}\nCannot open the file as archive\n\n"

def do_info(opts):
    if not opts.bare:
        STREAMS.out(banner_text())
    # INFO starts with "\nFormats" in direct stream, plus in normal mode banner is out then an extra blank line from out? Our INFO text starts '\nFormats'; original stdout after banner has "\n\nFormats": banner ends '\n', INFO text starts '\n', and another '\n' printed by main after banner? Actual full normal info stdout: banner (ends \n) + "\n\nFormats..." . In -ba mode stdout is "\nFormats..." (INFO). So normal print out('\n') post-banner before direct.
    if not opts.bare:
        STREAMS.out("\n")
    from cli import INFO
    STREAMS.direct(INFO)
    return 0

def print_time_stats(opts):
    if opts.show_time:
        import time
        elapsed=time.time()-(opts.start_time or time.time())
        # Kernel/User from resource usage
        import resource
        ru=resource.getrusage(resource.RUSAGE_SELF); user=ru.ru_utime; syst=ru.ru_stime; proc=user+syst
        def pct(x): return int(round(x/elapsed*100)) if elapsed>0 else 0
        STREAMS.out("\n")
        STREAMS.out(f"Kernel  Time = {syst:9.3f} = {pct(syst):4d}%\n")
        STREAMS.out(f"User    Time = {user:9.3f} = {pct(user):4d}%\n")
        STREAMS.out(f"Process Time = {proc:9.3f} = {pct(proc):4d}%\n")
        STREAMS.out(f"Global  Time = {elapsed:9.3f} =  100%\n")

def do_list(opts):
    if not opts.bare: STREAMS.out(banner_text())
    # bare: no banner and no scanning
    if opts.disable_archive_name:
        archive_name=None
        if not opts.include_archive_specs and not opts.stdin:
            raise CmdLineError("Cannot find archive name",2)
        file_patterns=opts.positionals
    else:
        if not opts.positionals: raise CmdLineError("Cannot find archive name",2)
        archive_name=opts.positionals[0]; file_patterns=opts.positionals[1:]
    specs=positional_specs(opts,file_patterns,True)
    # archive scanning
    if not opts.bare: STREAMS.out("\nScanning the drive for archives:\n")
    if opts.stdin and opts.disable_archive_name:
        # stdin archive path case - handled later
        cands=[ArchiveCandidate('-','',0)]; warnings=[]
    else:
        cands,warnings=scan_archives(opts,archive_name)
    # literal nonexistent handling: if archive_name has no wildcards and no include and file not exists
    if not cands:
        # differentiate wildcard vs literal missing
        if archive_name and ('*' in archive_name or '?' in archive_name or opts.include_archive_specs):
            raise CmdLineError("Cannot find archive",2)
        elif archive_name:
            # errno
            # If scanning warnings contain relevant warning, preserve path from warning? For plain missing name, scanner warns with original.
            raise SystemErrorMsg(f"errno=2 : No such file or directory\n{archive_name}\n")
        else:
            raise CmdLineError("Cannot find archive",2)
    if warnings and not opts.bare:
        # For archive scan, warnings of broken symlink become fatal system error (approx). If original spec is a directory, scanner warning path leads. We'll if all candidates maybe still proceed? For now only fatal if no wildcard and first warning originates during scanning a directory.
        pass
    total_size=sum(c.size for c in cands)
    if not opts.bare: STREAMS.out(f"{len(cands)} file{'' if len(cands)==1 else 's'}, {util.size_descr(total_size)}\n")
    _archive_scan_progress(opts,cands)
    total_stats={'folders':0,'files':0,'size':0,'compressed':0,'size_known':True}
    any_error=False; total_volumes=0; total_archives_size=0; listed_archives=0
    totals_items=[]
    octx=OpenContext(opts)
    for cand in cands:
        # guide
        STREAMS.listout(f"\nListing archive: {cand.display}\n")
        try:
            if opts.stdin and opts.disable_archive_name:
                data=sys.stdin.buffer.read(); archive=openarc.open_archive_data(data,cand.display,octx.dict())
            else:
                archive=openarc.open_archive_file(cand.fs_path,cand.display,octx.dict())
        except OpenArchiveError as e:
            if getattr(e,'need_password',False):
                # Password prompt behavior at open: original prompts before failing when no password given. Our parser tried get_password if provided in opts for header; if stdin EOF break should propagate.
                pass
            STREAMS.err(open_error_texts(cand.display,e,True))
            STREAMS.listout("\n\nErrors: 1\n")
            any_error=True; listed_archives+=1; total_volumes+=1; total_archives_size+=cand.size
            continue
        listed_archives+=1
        total_archives_size+= archive.total_physical if archive.is_split_container else archive.physical_size
        total_volumes+= archive.volumes
        if not opts.bare:
            STREAMS.listout("\n")
            STREAMS.listout(format_archive_header(archive,True))
        items=[it for it in archive.items if item_selected(it,specs,opts.exclude_specs,opts)]
        # Exclude anti? Listing shows anti items? They are listed probably.
        totals_items.extend(items)
        if not opts.bare: STREAMS.listout("\n")
        if opts.tech_info:
            body=list_archive_body(archive,items,opts,opts.bare)
            STREAMS.listout(body)
            stats=_stats_from_items(items)
        else:
            txt,stats=list_table(archive,items,opts,opts.bare)
            STREAMS.listout(txt)
        total_stats['folders']+=stats['folders']; total_stats['files']+=stats['files']; total_stats['compressed']+=stats['compressed']
        if stats['size'] is None: total_stats['size_known']=False
        else: total_stats['size']+=stats['size']
        if archive.warnings_count and not opts.bare:
            STREAMS.listout(f"\nWarnings: {archive.warnings_count}\n")
    # multi archive footer
    if not opts.bare and (listed_archives>1 or total_volumes>1):
        # table total if not tech info
        if not opts.tech_info:
            STREAMS.listout("\n")
            sep="------------------- ----- ------------ ------------  ------------------------"
            STREAMS.listout(sep+"\n")
            count=f"{total_stats['files']} files"
            if total_stats['folders']: count+=f", {total_stats['folders']} folders"
            tsize=f"{total_stats['size']:>12}" if total_stats['size_known'] else ' '*12
            STREAMS.listout(f"{max_datetime_text(totals_items):<19} {'':<5} {tsize} {total_stats['compressed']:>12}  {count}\n")
        STREAMS.listout(f"\nArchives: {listed_archives}\n")
        STREAMS.listout(f"Volumes: {total_volumes}\n")
        STREAMS.listout(f"Total archives size: {total_archives_size}\n")
    print_time_stats(opts)
    return 2 if any_error else 0

def _stats_from_items(items):
    f=sum(1 for i in items if i.is_dir); files=len(items)-f; size=sum(i.size or 0 for i in items); comp=sum(i.packed_size or 0 for i in items)
    return {'folders':f,'files':files,'size':size,'compressed':comp}

def _archive_scan_progress(opts,cands):
    if STREAMS.progress_enabled():
        for c in cands:
            txt=f"  0M Scan {os.path.dirname(c.display)+'/' if os.path.dirname(c.display) else ''}"
            STREAMS.progress(txt + "\x08"*len(txt) + " "*len(txt) + "\x08"*len(txt))

class ArchiveResult:
    def __init__(self):
        self.files=0; self.folders=0; self.size=0; self.compressed=0; self.errors=0; self.warnings=0; self.ok=True

def do_extract_test(opts, is_test=False, flat=False):
    cmd_word='Testing' if is_test else 'Extracting'
    if not opts.bare and not opts.stdout_data: STREAMS.out(banner_text())
    if opts.disable_archive_name:
        archive_name=None; file_patterns=opts.positionals
        if not opts.include_archive_specs and not opts.stdin: raise CmdLineError("Cannot find archive name",2)
    else:
        if not opts.positionals: raise CmdLineError("Cannot find archive name",2)
        archive_name=opts.positionals[0]; file_patterns=opts.positionals[1:]
    specs=positional_specs(opts,file_patterns,True)
    if not opts.bare: STREAMS.out("\nScanning the drive for archives:\n")
    if opts.stdin and opts.disable_archive_name:
        cands=[ArchiveCandidate('-','',0)]; warnings=[]
    else:
        cands,warnings=scan_archives(opts,archive_name)
    if not cands:
        if archive_name and ('*' in archive_name or '?' in archive_name or opts.include_archive_specs): raise CmdLineError("Cannot find archive",2)
        elif archive_name: raise SystemErrorMsg(f"errno=2 : No such file or directory\n{archive_name}\n")
        else: raise CmdLineError("Cannot find archive",2)
    total_size=sum(c.size for c in cands)
    if not opts.bare: STREAMS.out(f"{len(cands)} file{'' if len(cands)==1 else 's'}, {util.size_descr(total_size)}\n")
    _archive_scan_progress(opts,cands)
    octx=OpenContext(opts)
    total=ArchiveResult(); total_archives=0; ok_archives=0; cant_open=0; arch_with_errors=0; arch_with_warnings=0; sub_errors=0
    any_fatal=False
    for cand in cands:
        total_archives+=1
        STREAMS.out(f"\n{cmd_word} archive: {cand.display}\n")
        try:
            if opts.stdin and opts.disable_archive_name:
                data=sys.stdin.buffer.read(); archive=openarc.open_archive_data(data,cand.display,octx.dict())
            else: archive=openarc.open_archive_file(cand.fs_path,cand.display,octx.dict())
        except OpenArchiveError as e:
            STREAMS.err(open_error_texts(cand.display,e,False)); cant_open+=1; any_fatal=True; continue
        except BreakSignal: raise
        # open warning block
        if archive.open_warning and not opts.bare:
            pref=None
            # parse from open_warning string
            # It is "Open WARNING: Cannot open the file as [X] archive"
            m=re.search(r'\[(.+)\]',archive.open_warning); pref=m.group(1) if m else ''
            actual=archive.type_name
            STREAMS.out(f"WARNING:\n{cand.display}\nCannot open the file as [{pref}] archive\nThe file is open as [{actual}] archive\n\n")
            arch_with_warnings+=1
        STREAMS.out(format_archive_header(archive,False))
        res,errs,warns=process_archive_extract(archive,specs,opts,is_test,flat,cand)
        if errs:
            arch_with_errors+=1; sub_errors+=errs; any_fatal=True
        else: ok_archives+=1
        if warns: arch_with_warnings+=1
        # per archive final line(s) are emitted in process function for single; for multiple it emits Everything then blank line via next guide? process handles summary only if single?
        # We'll let process return stats and emit its own per-archive report (not aggregate summary).
        total.files+=res.files; total.folders+=res.folders; total.size+=res.size; total.compressed+=res.compressed
    # aggregate if >1 archives
    if total_archives>1 and not opts.bare:
        STREAMS.out("\n")
        STREAMS.out(f"Archives: {total_archives}\n")
        if ok_archives: STREAMS.out(f"OK archives: {ok_archives}\n")
        if arch_with_warnings: STREAMS.out(f"Archives with Warnings: {arch_with_warnings}\n")
        if arch_with_errors: STREAMS.out(f"Archives with Errors: {arch_with_errors}\n")
        if cant_open: STREAMS.out(f"Can't open as archive: {cant_open}\n")
        if sub_errors and not arch_with_errors: STREAMS.out(f"Sub items Errors: {sub_errors}\n")
        _print_extract_stats(total)
    print_time_stats(opts)
    return 2 if any_fatal else 0

def _print_extract_stats(res):
    if res.folders: STREAMS.out(f"Folders: {res.folders}\n")
    if res.folders or res.files!=1: STREAMS.out(f"Files: {res.files}\n")
    STREAMS.out(f"{'Size:':<12}{res.size}\n")
    STREAMS.out(f"{'Compressed:':<12}{res.compressed}\n")

def process_archive_extract(archive,specs,opts,is_test,flat,cand):
    # Returns (res, errors, warnings)
    res=ArchiveResult(); res.compressed=archive.total_physical if archive.is_split_container else archive.physical_size
    all_items=archive.items
    selected=[]; selected_set=set()
    for it in all_items:
        if item_selected(it,specs,opts.exclude_specs,opts): selected.append(it); selected_set.add(id(it))
    # For 7z solid stats, compute processed items list (for stats and CRC testing of skipped)
    processed_for_stats=[]
    if archive.type_name=='7z' or (archive.is_split_container and archive.inner and archive.inner.type_name=='7z'):
        by_folder={}
        for it in all_items:
            fi=it.user_data.get('folder_idx')
            if fi is not None: by_folder.setdefault(fi,[]).append(it)
        processed_ids=set(id(x) for x in selected if not x.is_dir)
        # folders/empty selected also processed for folder stats
        for fi,its in by_folder.items():
            sel_idx=[i for i,it in enumerate(its) if id(it) in selected_set]
            if sel_idx:
                for it in its[:max(sel_idx)+1]: processed_ids.add(id(it))
        processed_for_stats=[it for it in all_items if id(it) in processed_ids]
    else:
        processed_for_stats=selected[:]
    # stats folders/files: folder items among selected count as folders; processed_for_stats files count
    res.folders=sum(1 for it in selected if it.is_dir)
    # tar links: file count based on extract_size_count rules: count only regular files with streams? For tar, sym/hard links don't count file stats.
    def counts_as_file(it):
        if it.is_dir: return False
        if archive.type_name=='tar' and (it.symlink or it.hardlink): return False
        if it.extract_size_count is not None: return it.extract_size_count!=0
        return True
    res.files=sum(1 for it in processed_for_stats if counts_as_file(it))
    res.size=sum((it.size or 0) for it in processed_for_stats if counts_as_file(it))
    # For single stream formats with size unknown (bzip), size will be set after extraction from actual data lengths.
    errors=0; warnings=0
    actual_sizes=0
    _extract_progress_start(opts)
    if opts.log_level>=1 and not opts.stdout_data and not opts.bare:
        STREAMS.out("\n")
    if not selected and not opts.bare:
        # original prints blank line before No files
        STREAMS.out("\n\nNo files to process\n")
    elif not opts.bare and not opts.stdout_data:
        STREAMS.out("\n")
    outdir=opts.output_dir
    overwrite_state={'mode':opts.overwrite_mode}  # can become 'a' 's' 'u' 't' via prompts
    if opts.yes and overwrite_state['mode'] is None: overwrite_state['mode']='a'
    seen_targets={}
    for it in all_items:
        is_selected=id(it) in selected_set
        in_processed=id(it) in {id(x) for x in processed_for_stats}
        if not in_processed and not is_selected: continue
        # Folder items: if selected, create dir and log; if not selected but processed (shouldn't happen for folders), skip
        if it.is_dir:
            if not is_test and is_selected and not opts.stdout_data:
                target=extract_target(it,opts,flat,outdir)
                if opts.log_level>=1 and not opts.bare: STREAMS.out(f"- {it.path}\n")
                try: os.makedirs(target,exist_ok=True); _set_item_times_mode(target,it,True)
                except OSError as e:
                    errors+=1; STREAMS.err(f"ERROR: {util.errno_text(e)} : {it.path}\n")
            else:
                if it.path and opts.log_level>=1 and is_selected and not opts.bare: STREAMS.out(f"- {it.path}\n")
            continue
        # Determine extraction path target only if selected and not test
        data=None
        # We need data for test, selected, or processed skipped in 7z solid (for CRC validation)
        need_data=is_test or is_selected or in_processed
        try:
            if it.symlink:
                data=it.symlink.encode()
            else:
                # Hash formats handle themselves
                if archive.type_name=='Hash' or (archive.inner and archive.inner.type_name=='Hash'):
                    data=openarc.get_item_data(archive,it,{'password':opts.password})  # may raise DataError with messages
                else:
                    # supply password callback only if encrypted
                    oo={'password':opts.password,'get_password':OpenContext(opts).pwm.get if False else None}
                    # Use shared pwm from a context stored in opts? simpler: create pwm once in opts
                    pwm=getattr(opts,'_pwm',None)
                    if pwm is None:
                        pwm=PasswordManager(opts); opts._pwm=pwm
                    oo={'password':opts.password,'get_password':pwm.get}
                    data=openarc.get_item_data(archive,it,oo)
        except BreakSignal: raise
        except DataErrorItem as e:
            errors+=1
            STREAMS.err(f"ERROR: {e.msg} : {it.path}\n")
            # If extracting, 7zip may leave partial file with data up to error for some formats; for CRC mismatches after full decode below we handle separately.
            continue
        except Exception as e:
            errors+=1; STREAMS.err(f"ERROR: Data Error : {it.path}\n"); continue
        # Validation CRC / hashes
        if data is not None:
            actual_sizes+=len(data)
            crc_ok=True
            if it.crc is not None and archive.type_name not in ('gzip',): # gzip checked inside decoder
                if (zlib.crc32(data)&0xFFFFFFFF)!=it.crc: crc_ok=False
            # for zip AE2 crc None; for tar no crc field
            if not crc_ok:
                # If encrypted, message differs
                if it.encrypted:
                    # 7z encrypted data error will usually have been raised as Data Error; zip traditional wrong pw may reach here
                    if archive.type_name=='zip': STREAMS.err(f"ERROR: Wrong password : {it.path}\n")
                    else: STREAMS.err(f"ERROR: Data Error in encrypted file. Wrong password? : {it.path}\n")
                else:
                    STREAMS.err(f"ERROR: CRC Failed : {it.path}\n")
                errors+=1
                # For extract, original still writes the (corrupt) file to disk before CRC check. We'll continue to writing below.
                if is_test: continue
            # scrc hash verification for extract/test? If -scrc specified non-CRC32, original might not verify per file against stored CRC (just hash calculation in some formats). Ignore for now.
        if not is_selected:
            continue
        if opts.log_level>=1 and not opts.bare and not opts.stdout_data:
            STREAMS.out(f"- {it.path}\n")
        if is_test:
            continue
        if opts.stdout_data:
            try: sys.stdout.buffer.write(data); sys.stdout.buffer.flush()
            except BrokenPipeError: raise BreakSignal()
            continue
        # extract to filesystem
        target=extract_target(it,opts,flat,outdir)
        # handle symlink item (mode symlink or tar symlink)
        is_link = bool(it.symlink) or (it.mode is not None and ((it.mode>>12)&0xF)==10 and archive.type_name in ('7z','zip'))
        link_target=it.symlink
        if is_link and not link_target:
            try: link_target=data.decode('utf-8')
            except: link_target=data.decode('latin-1')
        if it.hardlink:
            # create hard link to already extracted target path
            src_target=_target_for_archive_path(it.hardlink,opts,flat,outdir)
            decision,final_target=_overwrite_decision(target,it,opts,overwrite_state)
            if decision=='skip': continue
            if decision=='break': raise BreakSignal()
            try:
                if os.path.lexists(final_target): os.remove(final_target)
                parent=os.path.dirname(final_target)
                if parent: os.makedirs(parent,exist_ok=True)
                os.link(src_target,final_target)
            except OSError as e:
                # fallback copy data
                try:
                    with open(final_target,'wb') as f: f.write(data)
                except OSError as e2:
                    errors+=1; STREAMS.err(f"ERROR: {util.errno_text(e2)} : {it.path}\n")
            continue
        if is_link:
            decision,final_target=_overwrite_decision(target,it,opts,overwrite_state)
            if decision=='skip': continue
            if decision=='break': raise BreakSignal()
            try:
                if os.path.lexists(final_target): os.remove(final_target)
                parent=os.path.dirname(final_target)
                if parent: os.makedirs(parent,exist_ok=True)
                os.symlink(link_target,final_target)
                _set_item_times_mode(final_target,it,False,not_follow=True)
            except OSError as e:
                errors+=1; STREAMS.err(f"ERROR: {util.errno_text(e)} : {it.path}\n")
            continue
        # regular/special
        decision,final_target=_overwrite_decision(target,it,opts,overwrite_state)
        if decision=='skip': continue
        if decision=='break': raise BreakSignal()
        try:
            parent=os.path.dirname(final_target)
            if parent: os.makedirs(parent,exist_ok=True)
            if it.mode is not None and ((it.mode>>12)&0xF)==1:
                # FIFO
                if os.path.lexists(final_target): os.remove(final_target)
                os.mkfifo(final_target)
            else:
                with open(final_target,'wb') as f: f.write(data)
            _set_item_times_mode(final_target,it,False)
        except OSError as e:
            errors+=1; STREAMS.err(f"ERROR: {util.errno_text(e)} : {it.path}\n")
    # Adjust res Size for formats where item size unknown (bzip/zstd) using actual decoded sizes
    if archive.type_name in ('bzip2','zstd','lzma','lzma86'):
        res.size=actual_sizes
    # Per-archive summary lines
    total_archives_hint=getattr(opts,'_total_archives_hint',1)
    if not opts.bare and not opts.stdout_data:
        if errors==0:
            STREAMS.out("Everything is Ok\n")
        else:
            STREAMS.out("\n")
            STREAMS.out(f"Sub items Errors: {errors}\n")
        # if this is single archive operation OR multiple, original prints per archive summary stats only when single; for multiple, it prints Everything without stats per archive.
        # Caller sets opts._multi flag before loop.
        if not getattr(opts,'_multi',False):
            if archive.warnings_count:
                STREAMS.out("\n")
                STREAMS.out(f"Archives with Warnings: 1\n")
            if errors:
                STREAMS.out("\nArchives with Errors: 1\n\n")
                STREAMS.out(f"Sub items Errors: {errors}\n")
            else:
                STREAMS.out("\n"); _print_extract_stats(res)
    return res,errors,warnings

def _extract_progress_start(opts):
    if STREAMS.progress_enabled(): STREAMS.progress("  0%")

def sanitize_path_components(path):
    parts=[]
    for p in path.replace('\\','/').split('/'):
        if p=='' or p=='.' or p=='..': continue
        parts.append(p)
    return parts

def extract_target(item,opts,flat,outdir):
    p=item.path
    if flat:
        base=os.path.basename(p.rstrip('/'))
        parts=[base] if base else []
    else:
        parts=sanitize_path_components(p)
        if opts.eliminate_root:
            # -spe: if all items share common root and output dir ends with it? Actual rules complicated; basic: if output dir basename equals first part, strip it
            if outdir and parts and os.path.basename(os.path.abspath(outdir))==parts[0]: parts=parts[1:]
    rel=os.path.join(*parts) if parts else ''
    return os.path.join(outdir,rel) if outdir else rel

def _target_for_archive_path(path,opts,flat,outdir):
    parts=[os.path.basename(path)] if flat else sanitize_path_components(path)
    rel=os.path.join(*parts) if parts else ''
    return os.path.join(outdir,rel) if outdir else rel

def _overwrite_decision(target,item,opts,state):
    if not os.path.lexists(target): return 'write',target
    mode=state['mode']
    if mode=='a': return 'write',target
    if mode=='s': return 'skip',target
    if mode=='u': return 'write',_auto_rename(target)
    if mode=='t':
        renamed=_auto_rename(target); 
        try: os.rename(target,renamed)
        except: pass
        return 'write',target
    # ask
    try: st=os.stat(target); esize=st.st_size; emod=time.strftime('%Y-%m-%d %H:%M:%S',time.localtime(st.st_mtime))
    except: esize=0; emod=''
    STREAMS.out(f"\nWould you like to replace the existing file:\n  Path:     {target}\n  Size:     {util.size_descr(esize)}\n  Modified: {emod}\nwith the file from archive:\n  Path:     {item.path}\n  Size:     {util.size_descr(item.size or 0)}\n  Modified: {item.datetime_text_nofrac()}\n? (Y)es / (N)o / (A)lways / (S)kip all / A(u)to rename all / (Q)uit? ")
    # read one char / line from stdin (original reads from console). In pipe it reads line.
    try:
        if sys.stdin.isatty():
            ch=_read_console_char()
            STREAMS.out("\n")
        else:
            line=sys.stdin.readline()
            if line=='': raise BreakSignal()
            ch=line.strip()
    except EOFError: raise BreakSignal()
    if not ch: raise BreakSignal()
    c=ch[0].lower()
    if c=='y': return 'write',target
    if c=='n': return 'skip',target
    if c=='a': state['mode']='a'; return 'write',target
    if c=='s': state['mode']='s'; return 'skip',target
    if c=='u': state['mode']='u'; return 'write',_auto_rename(target)
    if c=='q': raise BreakSignal()
    # unknown input: original asks again? In non-tty maybe repeats prompt. Simplify recurse
    return _overwrite_decision(target,item,opts,state)

def _read_console_char():
    try:
        import termios,tty
        fd=sys.stdin.fileno(); old=termios.tcgetattr(fd)
        try: tty.setraw(fd); ch=sys.stdin.read(1)
        finally: termios.tcsetattr(fd,termios.TCSADRAIN,old)
        return ch
    except Exception:
        return sys.stdin.read(1)

def _auto_rename(path):
    dirn=os.path.dirname(path); base=os.path.basename(path)
    name,ext=os.path.splitext(base)
    i=1
    while True:
        cand=os.path.join(dirn,f"{name}_{i}{ext}")
        if not os.path.lexists(cand): return cand
        i+=1

def _set_item_times_mode(target,item,is_dir,not_follow=False):
    # mode
    try:
        if item.mode is not None and not not_follow:
            os.chmod(target,item.mode & 0o7777)
        elif item.attr is not None and item.mode is not None and not not_follow:
            os.chmod(target,item.mode & 0o7777)
    except Exception: pass
    if item.mtime_ns is not None:
        try:
            os.utime(target,ns=(item.accessed_ns or item.mtime_ns,item.mtime_ns),follow_symlinks=not not_follow)
        except Exception: pass
