def _print_extract_stats(res):
    if res.folders: STREAMS.out(f"Folders: {res.folders}\n")
    if res.folders or res.files!=1: STREAMS.out(f"Files: {res.files}\n")
    STREAMS.out(f"{'Size:':<12}{res.size}\n")
    STREAMS.out(f"{'Compressed:':<12}{res.compressed}\n")

