def _extract_progress_start(opts):
    if STREAMS.progress_enabled(): STREAMS.progress("  0%")

def sanitize_path_components(path):
    parts=[]
    for p in path.replace('\\','/').split('/'):
        if p=='' or p=='.' or p=='..': continue
        parts.append(p)
    return parts

def extract_target(item,opts,flat,outdir):
    p=item.path
    if flat:
        base=os.path.basename(p.rstrip('/'))
        parts=[base] if base else []
    else:
        parts=sanitize_path_components(p)
        if opts.eliminate_root:
            # -spe: if all items share common root and output dir ends with it? Actual rules complicated; basic: if output dir basename equals first part, strip it
            if outdir and parts and os.path.basename(os.path.abspath(outdir))==parts[0]: parts=parts[1:]
    rel=os.path.join(*parts) if parts else ''
    return os.path.join(outdir,rel) if outdir else rel

def _target_for_archive_path(path,opts,flat,outdir):
    parts=[os.path.basename(path)] if flat else sanitize_path_components(path)
    rel=os.path.join(*parts) if parts else ''
    return os.path.join(outdir,rel) if outdir else rel

def _overwrite_decision(target,item,opts,state):
    if not os.path.lexists(target): return 'write',target
    mode=state['mode']
    if mode=='a': return 'write',target
    if mode=='s': return 'skip',target
    if mode=='u': return 'write',_auto_rename(target)
    if mode=='t':
        renamed=_auto_rename(target); 
        try: os.rename(target,renamed)
        except: pass
        return 'write',target
    # ask
    try: st=os.stat(target); esize=st.st_size; emod=time.strftime('%Y-%m-%d %H:%M:%S',time.localtime(st.st_mtime))
    except: esize=0; emod=''
    STREAMS.out(f"\nWould you like to replace the existing file:\n  Path:     {target}\n  Size:     {util.size_descr(esize)}\n  Modified: {emod}\nwith the file from archive:\n  Path:     {item.path}\n  Size:     {util.size_descr(item.size or 0)}\n  Modified: {item.datetime_text_nofrac()}\n? (Y)es / (N)o / (A)lways / (S)kip all / A(u)to rename all / (Q)uit? ")
    # read one char / line from stdin (original reads from console). In pipe it reads line.
    try:
        if sys.stdin.isatty():
            ch=_read_console_char()
            STREAMS.out("\n")
        else:
            line=sys.stdin.readline()
            if line=='': raise BreakSignal()
            ch=line.strip()
    except EOFError: raise BreakSignal()
    if not ch: raise BreakSignal()
    c=ch[0].lower()
    if c=='y': return 'write',target
    if c=='n': return 'skip',target
    if c=='a': state['mode']='a'; return 'write',target
    if c=='s': state['mode']='s'; return 'skip',target
    if c=='u': state['mode']='u'; return 'write',_auto_rename(target)
    if c=='q': raise BreakSignal()
    # unknown input: original asks again? In non-tty maybe repeats prompt. Simplify recurse
    return _overwrite_decision(target,item,opts,state)

def _read_console_char():
    try:
        import termios,tty
        fd=sys.stdin.fileno(); old=termios.tcgetattr(fd)
        try: tty.setraw(fd); ch=sys.stdin.read(1)
        finally: termios.tcsetattr(fd,termios.TCSADRAIN,old)
        return ch
    except Exception:
        return sys.stdin.read(1)

def _auto_rename(path):
    dirn=os.path.dirname(path); base=os.path.basename(path)
    name,ext=os.path.splitext(base)
    i=1
    while True:
        cand=os.path.join(dirn,f"{name}_{i}{ext}")
        if not os.path.lexists(cand): return cand
        i+=1

def _set_item_times_mode(target,item,is_dir,not_follow=False):
    # mode
    try:
        if item.mode is not None and not not_follow:
            os.chmod(target,item.mode & 0o7777)
        elif item.attr is not None and item.mode is not None and not not_follow:
            os.chmod(target,item.mode & 0o7777)
    except Exception: pass
    if item.mtime_ns is not None:
        try:
            os.utime(target,ns=(item.accessed_ns or item.mtime_ns,item.mtime_ns),follow_symlinks=not not_follow)
        except Exception: pass
