def _canonical_coder_name(nm):
    m={'copy':'Copy','lzma':'LZMA','lzma2':'LZMA2','bzip2':'BZip2','deflate':'Deflate','deflate64':'Deflate64','ppmd':'PPMD','delta':'Delta','bcj':'BCJ','bcj2':'BCJ2','ppc':'PPC','ia64':'IA64','arm':'ARM','armt':'ARMT','sparc':'SPARC','arm64':'ARM64','riscv':'RISCV','swap2':'Swap2','swap4':'Swap4','7zaes':'7zAES','aes256cbc':'AES256CBC'}
    return m.get((nm or '').strip().lower())

def _boolval(v,default=True):
    if v is None or v=='': return default
    return v.lower() not in ('off','false','0','no','-')

def _parse_dict_value(v):
    if v is None: return None
    s=v.strip().lower()
    if not s: return None
    if s.endswith('b'): return int(s[:-1])
    if s.endswith('k'): return int(s[:-1])*1024
    if s.endswith('m'): return int(s[:-1])*1024*1024
    if s.endswith('g'): return int(s[:-1])*1024*1024*1024
    n=int(s)
    if n>31: raise ValueError('dict exponent too large')
    return 1<<n

def parse_size_value(s):
    if s is None: return None
    st=s.strip().lower(); mult=1
    if st.endswith('b'): st=st[:-1]
    elif st.endswith('k'): mult=1024; st=st[:-1]
    elif st.endswith('m'): mult=1024**2; st=st[:-1]
    elif st.endswith('g'): mult=1024**3; st=st[:-1]
    return int(float(st))*mult if st else 0

def _split_method_params(raw):
    # Returns list (name,val,has_eq). Splits on ':' but method params can be like 0=LZMA2:d=1m:fb=32
    parts=[]; cur=''
    segs=raw.split(':')
    for seg in segs:
        if '=' in seg:
            k,v=seg.split('=',1); parts.append((k,v,True))
        else:
            # Bare param like qs, mt2, x9, fb32, d1m, hc, s, etc or coder name in chained value?
            # Try decipher prefix names longest known
            parts.append(_parse_bare_method(seg))
    return parts

def _parse_bare_method(seg):
    # Known bare prefixes where value is concatenated
    # Order by len desc
    known=['qs','hc','he','em','mt','tm','tc','ta','cu','cp','fb','lc','lp','pb','mf','x','d','a','s','e','o','m']
    low=seg.lower()
    for k in known:
        if low.startswith(k):
            return (k,seg[len(k):],False)
    # digit index e.g. 0LZMA? unusual
    return (seg,'',False)

