def write_output_archive(final_name,data,opts):
    if opts.volumes:
        sizes=[parse_size_value(v) for v in opts.volumes]
        # delete existing volume files matching pattern?
        pos=0; idx=1; count=0; total=len(data)
        while pos<total or idx==1:
            vsz=sizes[min(idx-1,len(sizes)-1)] if sizes else total
            if vsz is None or vsz<=0: vsz=total-pos
            chunk=data[pos:pos+vsz]; pos+=len(chunk); count+=1
            vname=f"{final_name}.{idx:03d}"; idx+=1
            with open(vname,'wb') as f: f.write(chunk)
            if pos>=total: break
        return count
    # write via temp in work dir / same dir
    dest=final_name
    workdir=opts.work_dir if opts.work_dir else os.path.dirname(os.path.abspath(dest))
    # If workdir specified empty -> temp dir system
    if opts.work_dir_specified and opts.work_dir=='':
        import tempfile; workdir=tempfile.gettempdir()
    try:
        fd,tmp=tempfile.mkstemp(prefix='7z',dir=workdir) if False else (None,None)
    except: tmp=None
    # Simpler atomic-ish: write to dest directly but preserve old if error already handled. Original uses temp then rename, observable only on failure. We'll write to tmp in dest dir.
    import tempfile
    ddir=os.path.dirname(os.path.abspath(dest)) if os.path.dirname(dest) else '.'
    fd,tmp=tempfile.mkstemp(dir=ddir,prefix='.7z')
    try:
        with os.fdopen(fd,'wb') as f: f.write(data)
        os.rename(tmp,dest)
    except:
        try: os.remove(tmp)
        except: pass
        raise
    return 1
