# ------ method / compression options parsing ------
def parse_method_options(opts, archive_type):
    # Returns comp dict; may set opts._method_error for delayed error
    comp={'level':5,'coders':None,'zip_method':'Deflate','header_compression':True,'header_encryption':False,
          'solid':True,'solid_spec':None,'dict_size':None,'nice_len':None,'mf':None,'lc':3,'lp':0,'pb':2,'algo_fast':False,
          'password':None,'threads':None,'qs_sort_by_type':False,'store_ctime':False,'store_atime':False,'store_mtime':True,'zip_utf8':False,'xz_check':'CRC32','sfx':opts.sfx}
    # defaults by level later
