                    pass
                elif lname=='d' or lname=='dict':
                    comp['dict_size']=_parse_dict_value(val)
                elif lname=='fb': comp['nice_len']=int(val)
                elif lname=='lc': comp['lc']=int(val)
                elif lname=='lp': comp['lp']=int(val)
                elif lname=='pb': comp['pb']=int(val)
                elif lname=='a': comp['algo_fast']=(val=='0')
                elif lname=='mf':
                    import lzma as _lz; comp['mf']={'hc3':_lz.MF_HC3,'hc4':_lz.MF_HC4,'bt2':_lz.MF_BT2,'bt3':_lz.MF_BT3,'bt4':_lz.MF_BT4}.get(val.lower())
                    if comp['mf'] is None: errors.append(raw)
                elif lname=='s':
                    # solid -ms=...
                    if val.lower()=='off': comp['solid']=False
                    elif val.lower() in ('on',''): comp['solid']=True; comp['solid_spec']=None
                    else: comp['solid']=True; comp['solid_spec']=val
                elif lname=='hc': comp['header_compression']=_boolval(val,True)
                elif lname=='he': comp['header_encryption']=_boolval(val,True)
                elif lname=='qs': comp['qs_sort_by_type']=_boolval(val,True)
                elif lname=='em':
                    comp['encryption_method']=val
                    if val.upper().startswith('AES'):
                        comp['aes_strength']={ 'AES128':1,'AES192':2,'AES256':3}.get(val.upper(),3)
                elif lname=='m':
                    comp['zip_method']=val
                elif lname=='mem':
                    comp['ppmd_mem']=val
                elif lname=='o':
                    comp['ppmd_order']=int(val)
                elif lname=='tm': comp['store_mtime']=_boolval(val,True)
                elif lname=='tc': comp['store_ctime']=_boolval(val,True)
                elif lname=='ta': comp['store_atime']=_boolval(val,True)
                elif lname=='cu': comp['zip_utf8']=_boolval(val,True)
                elif lname=='cp': comp['code_page']=val
                elif lname=='crc': comp['xz_check']=val.upper()
                elif lname=='mt': comp['threads']=val
                elif lname=='e': comp['zip_lzma_eos']=_boolval(val,True) # ? m e for zip LZMA eos?
                else:
                    # Could be a method specification like "LZMA2" as whole raw (e.g. -mLZMA?) or filter options b/c etc.
                    # Unknown name -> error delayed
                    # But common params with no = like -mqs (name qs, val '') handled. -ms etc name parsing: raw "s=off" split gives s. raw "qs" gives qs.
                    errors.append(raw)
            except Exception:
