def combined_name_digest(method,name,data,is_dir):
    # Reverse-engineered for CRC32/CRC64 regular files: H(data + Digest(16 zero bytes internal) + name_utf16le)
    # For other hashes and folders, approximate with same structural formula (patch = hash of 16 zero bytes in internal bytes)
    # Folder: patch differs; for CRC32 we solved emptydir/'a' cases but need general. Use regular formula with name including trailing slash for folders (approx).
    zero16=b'\x00'*16
    if method=='CRC32':
        patch_int=zlib.crc32(zero16)&0xFFFFFFFF; patch=struct.pack('<I',patch_int)
        val=zlib.crc32(data+patch+name.encode('utf-16le'))&0xFFFFFFFF; return struct.pack('<I',val)
    if method=='CRC64':
        patch=struct.pack('<Q',util.crc64(zero16)); val=util.crc64(data+patch+name.encode('utf-16le')); return struct.pack('<Q',val)
    if method=='SHA256':
        patch=hashlib.sha256(zero16).digest(); return hashlib.sha256(data+patch+name.encode('utf-16le')).digest()
    if method=='SHA1':
        patch=hashlib.sha1(zero16).digest(); return hashlib.sha1(data+patch+name.encode('utf-16le')).digest()
    if method=='XXH64':
        patch=struct.pack('<Q',util.xxh64(zero16)); return struct.pack('<Q',util.xxh64(data+patch+name.encode('utf-16le')))
    return b''

