        # patterns are pairs, validated in do_update? Validate here before messages except open already printed.
        if len(patterns)%2==1:
            raise CmdLineError(f"There is no second file name for rename pair:\n{patterns[-1]}",2)
        keep_old=list(old_items)
        # Apply renames in order mutating old item paths (for preserved writers user_data rename)
        for i in range(0,len(patterns),2):
            src=patterns[i]; dst=patterns[i+1]
            apply_rename(keep_old,src,dst,opts)
    else:
        keep_old=list(old_items)
    # Count stats for messages
    def stats_for_old(items):
        folders=sum(1 for x in items if x.is_dir); files=len(items)-folders; size=sum(x.size or 0 for x in items); return folders,files,size
    def stats_for_new(items):
        folders=sum(1 for x in items if x.is_dir); files=len(items)-folders
        size=0; known=True
        for x in items:
            if getattr(x.scan,'from_stdin',False): known=False
            else: size += x.size or 0
        return folders,files,size,known
    # Print creating/updating and stats messages
    if not opts.bare:
        if archive_exists:
            STREAMS.out(f"\nUpdating archive: {final_name}\n\n")
        else:
            STREAMS.out(f"\nCreating archive: {final_name}\n\n")
        if cmd=='d' and deleted_old:
            STREAMS.out("\n")
            f,fi,sz=stats_for_old(deleted_old); STREAMS.out(f"Delete data from archive: {util.num_files_str(f,fi,sz)}\n")
        if archive_exists and keep_old:
            f,fi,sz=stats_for_old(keep_old); STREAMS.out(f"Keep old data in archive: {util.num_files_str(f,fi,sz)}\n")
        # Add line
        f,fi,sz,known=stats_for_new(add_new)
        STREAMS.out(f"Add new data to archive: {util.num_files_str(f,fi,sz,known)}\n")
    # Hash type special: after Add, E_NOTIMPL
    if typ=='Hash':
        STREAMS.err("\nSystem ERROR:\nE_NOTIMPL : Not implemented\n"); return None
    # Method errors: if comp has errors that should generate E_INVALIDARG at encode time
    if comp.get('_errors'):
        STREAMS.err("\nSystem ERROR:\nE_INVALIDARG : One or more arguments are invalid\n"); return None
    # Resolve encryption password after Add message
    if opts.password_specified and typ in ('7z','zip'):
        if opts.password is None:
            pw=octx.pwm.get(); comp['password']=pw
        else: comp['password']=opts.password
    elif old_archive and old_items and any(getattr(x,'encrypted',False) for x in keep_old) and typ in ('7z','zip'):
        # if kept old items need repack but preserved as-is, no need. For partial repack we may need password - handled during decode prompt.
        pass
    # Single-stream validation before reading data? Original for multi-files prints Add then E_INVALIDARG before Files read and doesn't create archive. We'll validate final item counts below before producing bytes, after reading may have loaded.
    files_read=0; max_mtime=None
    def track(it):
        nonlocal max_mtime
        if it.mtime_ns is not None: max_mtime=it.mtime_ns if max_mtime is None or it.mtime_ns>max_mtime else max_mtime
    # Build bytes per type
    if typ=='7z':
        out_bytes,files_read=build_7z_final(opts,old_archive,keep_old,add_new,comp,octx,archive_exists)
        if out_bytes is None: return None
    elif typ=='zip':
        out_bytes,files_read=build_zip_final(opts,old_archive,keep_old,add_new,comp,octx)
        if out_bytes is None: return None
    elif typ=='tar':
        out_bytes,files_read=build_tar_final(opts,old_archive,keep_old,add_new,comp,octx)
        if out_bytes is None: return None
    elif typ in ('gzip','bzip2','xz'):
        final_items=keep_old_to_witems(keep_old,opts,octx)+new_to_witems(add_new,opts)
        # sort? if 2 items error before reading new data according to original messages; but reading data for one is needed. Validate count first:
        if len(final_items)!=1 or final_items[0].is_dir:
            STREAMS.err("\nSystem ERROR:\nE_INVALIDARG : One or more arguments are invalid\n"); return None
        it=final_items[0]
        # decide if it came from new items to count read
        is_new=any(it is x for x in add_new) or (it in add_new)
        data=read_any_item_data(it,opts,octx); it.data=data; it.size=len(data)
        if is_new: files_read=1 if len(data)>0 else 0
        # Original for -mx with gzip zip etc: reading file counts 1 even if empty? For single gz empty file, Files read likely1. Our existing files_read logic for 7z counts size>0; single-stream writer originally always reads the file stream. If new item empty, observed? We'll count 1 if from stdin or empty for gzip.
        if is_new and files_read==0: files_read=1
        wi=formats.ZipWItem(); wi.path=it.path; wi.data=data; wi.mtime_ns=it.mtime_ns; wi.mode=getattr(it,'mode',0o100644); wi.attr=getattr(it,'attr',None)
        if typ=='gzip': out_bytes=formats.write_gzip_archive(wi,comp)
        elif typ=='bzip2': out_bytes=formats.write_bzip2_archive(wi,comp)
        else: out_bytes=formats.write_xz_archive(wi,comp)
        track(it)
    else:
        STREAMS.err("\nSystem ERROR:\nE_NOTIMPL : Not implemented\n"); return None
    for x in keep_old+add_new: track(x)
    stats={'files_read':files_read,'max_mtime_ns':max_mtime,'total_size':len(out_bytes)}
    if opts.volumes:
        # count volumes as write will produce; calculate
        sizes=[parse_size_value(v) for v in opts.volumes]; pos=0; idx=0; cnt=0
        while pos<len(out_bytes) or cnt==0:
            vs=sizes[min(idx,len(sizes)-1)] if sizes else len(out_bytes); pos+=vs; cnt+=1; idx+=1
            if pos>=len(out_bytes): break
        stats['volumes_count']=cnt
    # SFX prefix handling: if opts.sfx is not None, this should have errored earlier before scan in do_update (module not found). We'll handle there.
    return out_bytes,stats

def apply_rename(items,src,dst,opts):
    # supports exact path/directory and wildcard with * in src/dst basename
    for it in items:
        # directory rename exact
        if it.path==src.rstrip('/') or it.path==src:
            it.path=dst
            if hasattr(it,'user_data'): it.user_data['renamed']=True
            continue
        if it.path.startswith(src.rstrip('/')+'/'):
            it.path=dst.rstrip('/')+it.path[len(src.rstrip('/')):]
            if hasattr(it,'user_data'): it.user_data['renamed']=True
            continue
        if '*' in src or '?' in src:
            # component wildcard matching full path; dst may contain * replaced by matched part? Basic: if path matches, if dst contains *, substitute wildcard segment capture from basename
            if archive_pattern_match(src,it.path,opts):
                newp=dst
                if '*' in dst:
                    # find matched text for first * in basename if src pattern is simple
                    base=os.path.basename(it.path); patbase=os.path.basename(src)
                    # capture using regex
                    rx='^'+re.escape(patbase).replace('\\*','(.*)').replace('\\?','(.)')+'$'; m=re.match(rx,base)
                    if m:
                        cap=m.group(1) if m.groups() else ''
                        newp=dst.replace('*',cap,1)
                it.path=newp
                if hasattr(it,'user_data'): it.user_data['renamed']=True

def keep_old_to_witems(keep_old,opts,octx):
    return keep_old[:]  # functions for other types handle Item too via read_any

def new_to_witems(add_new,opts):
    return add_new[:]

def read_any_item_data(item,opts,octx):
    # item can be NewDataItem or old archive Item
    if hasattr(item,'scan'):
        return read_new_item_data(item,opts)
    # old archive item: need archive reference stored where? Items don't point to archive; caller should pass data via archive-specific functions. This function is only used for single final where item may be old: need archive from opts._current_old_archive
    arc=getattr(opts,'_current_old_archive',None)
    if arc is None: return b''
    return openarc.get_item_data(arc,item,octx.dict())

def build_7z_final(opts,old_archive,keep_old,add_new,comp,octx,archive_exists):
    # Map old items into WItems and blocks
    dir_items=[]; empty_items=[]; blocks=[]; files_read=0
    # helper to create WItem from old/new
    def w_from_old(it):
        w=fmt7z.WItem(it.path,it.is_dir,it.size or 0,it.mtime_ns,it.attr,b'',it.anti,it.crc); w._old=it; return w
    def w_from_new(it):
        data=b''
        w=fmt7z.WItem(it.path,it.is_dir,it.size or 0,it.mtime_ns,it.attr,data,False,None); w._new=it; return w
    # folders/empty final
    for it in keep_old:
        if it.is_dir: dir_items.append(w_from_old(it))
        elif (it.size or 0)==0 and it.user_data.get('folder_idx') is None:
            empty_items.append(w_from_old(it))
    for it in add_new:
        if it.is_dir: dir_items.append(w_from_new(it))
        elif (it.size or 0)==0 and not getattr(it.scan,'from_stdin',False):
            # data may be symlink target with size len; it.size set accordingly for snl; for regular empty 0
            empty_items.append(w_from_new(it))
    dir_items.sort(key=lambda x:x.path); empty_items.sort(key=lambda x:x.path)
    # old blocks if old archive is 7z
    old_is_7z = old_archive and ((old_archive.inner.type_name if old_archive.is_split_container and old_archive.inner else old_archive.type_name)=='7z')
    old_arc_for_data=old_archive.inner if (old_archive and old_archive.is_split_container) else old_archive
    if old_is_7z:
        by_folder={}
        for it in keep_old:
            fi=it.user_data.get('folder_idx')
            if fi is not None: by_folder.setdefault(fi,[]).append(it)
        si=old_arc_for_data._si if hasattr(old_arc_for_data,'_si') else None
        for fi in sorted(by_folder):
            kept=by_folder[fi]
            all_in_folder=[x for x in old_arc_for_data.items if x.user_data.get('folder_idx')==fi]
            bl=fmt7z.WBlock()
            if len(kept)==len(all_in_folder):
                # preserved
                f=si.folders[fi]
                bl.preserved_folder=f; bl.items=[w_from_old(x) for x in kept]
                for w in bl.items: w._in_block=True
                # packed data raw
                start_pack_idx=getattr(f,'_pack_start_idx',0); npacked=len(f.packed_indices) if f.packed_indices else 1
                off=32+si.pack_pos+sum(si.pack_sizes[:start_pack_idx]); streams=[]
                for sz in si.pack_sizes[start_pack_idx:start_pack_idx+npacked]: streams.append(old_arc_for_data.data[off:off+sz]); off+=sz
                bl.packed_data=b''.join(streams); bl.pack_sizes=si.pack_sizes[start_pack_idx:start_pack_idx+npacked][:]
                bl.unpack_total=f.unpack_size()
                blocks.append(bl)
            else:
                bl.items=[]
                for x in kept:
                    w=w_from_old(x)
                    try: w.data=openarc.get_item_data(old_archive,x,octx.dict())
                    except DataErrorItem as e:
                        STREAMS.err(f"ERROR: {e.msg} : {x.path}\n"); return None,0
                    w.size=len(w.data); w._in_block=True; bl.items.append(w)
                # encode this rebuilt old block with current comp (folder method may change if switches specify)
                try: fmt7z.encode_block_new(bl,comp)
                except Exception: STREAMS.err("\nSystem ERROR:\nE_INVALIDARG : One or more arguments are invalid\n"); return None,0
                blocks.append(bl)
    else:
        # kept old items from another type become a new solid block(s) sorted as new blocks below; treat like add_old_items
        add_old_stream=[]
        for it in keep_old:
            if not it.is_dir and (it.size or 0)>0:
                w=w_from_old(it)
                try: w.data=openarc.get_item_data(old_archive,it,octx.dict())
                except Exception: w.data=b''
                w.size=len(w.data); add_old_stream.append(w)
        if add_old_stream:
            # these will be grouped with new items later as blocks (old before new)
            for chunk in _chunk_blocks(add_old_stream,comp,opts):
                bl=fmt7z.WBlock(); bl.items=chunk
                for w in chunk: w._in_block=True
                fmt7z.encode_block_new(bl,comp); blocks.append(bl)
    # new stream items
    new_stream=[]
    for it in add_new:
        if it.is_dir: continue
        # empty regular files already in empty_items unless stdin (size unknown) or symlink action
        if (it.size or 0)==0 and not getattr(it.scan,'from_stdin',False) and not it.symlink: continue
        w=w_from_new(it)
        # read data (logs)
        if opts.log_level>=1 and not opts.bare:
            pass
        data=read_new_item_data(it,opts); w.data=data; w.size=len(data)
        if len(data)>0 or it.symlink: files_read+=1
        new_stream.append(w)
    # stdin empty stream if size 0 becomes empty file
    stdin_empty=[w for w in new_stream if w.size==0]
    if stdin_empty:
        for w in stdin_empty:
            new_stream.remove(w); empty_items.append(w)
        empty_items.sort(key=lambda x:x.path)
    new_stream_sorted=sorted(new_stream,key=lambda x:( _qs_key(x.path) if comp.get('qs_sort_by_type') else x.path))
    for chunk in _chunk_blocks(new_stream_sorted,comp,opts):
        bl=fmt7z.WBlock(); bl.items=chunk
        for w in chunk: w._in_block=True
        # `-bb` logging for add: print + path for new items at encode time (after Add line, before Files read)
        if opts.log_level>=1 and not opts.bare:
            for w in chunk: STREAMS.out(f"+ {w.path}\n")
        # Also log folders/empty new in original order? Original -bb1 Add block logs have items order as they were added (sorted write order?) We'll log dirs/empty in separate handling below once.
        try: fmt7z.encode_block_new(bl,comp)
        except DataErrorItem as e:
            STREAMS.err("\nSystem ERROR:\nE_INVALIDARG : One or more arguments are invalid\n"); return None,files_read
        blocks.append(bl)
    if opts.log_level>=1 and not opts.bare:
        # log other new items (folders/empty) in path sorted combination with stream? Original -bb1 for simple a.txt c.log printed in sorted order as items were written. For folder+files it likely logs as items are processed in scan order? We'll approximate by logging dir/empty new before streams if not already: This ends up after stream logs. To minimize difference for common cases (only files), no effect.
        for w in dir_items+empty_items:
            if hasattr(w,'_new'): STREAMS.out(f"+ {w.path}\n")
    all_items=dir_items+empty_items
    for bl in blocks: all_items.extend(bl.items)
    # preserved block WItems need _in_block attr set already
    wopts={'header_compression':comp.get('header_compression',True),'header_encryption':comp.get('header_encryption',False) and comp.get('password'),'password':comp.get('password')}
    out=fmt7z.write_7z_archive(all_items,blocks,wopts)
    return out,files_read

def _qs_key(path):
    base=os.path.basename(path); ext=base.rsplit('.',1)[1].lower() if '.' in base else ''
    return (ext,path)

def _chunk_blocks(items,comp,opts):
    if not items: return []
    if not comp.get('solid',True): return [[x] for x in items]
    spec=comp.get('solid_spec')
    if not spec: return [items]
    s=str(spec).lower()
    if s.endswith('f'):
        try: n=int(s[:-1])
        except: return [items]
        return [items[i:i+n] for i in range(0,len(items),n)]
    # size spec
    try: maxsize=parse_size_value(s)
    except: return [items]
    chunks=[]; cur=[]; tots=0
    for it in items:
        if cur and tots+(it.size or 0)>maxsize: chunks.append(cur); cur=[]; tots=0
        cur.append(it); tots+=it.size or 0
    if cur: chunks.append(cur)
    return chunks

def build_zip_final(opts,old_archive,keep_old,add_new,comp,octx):
    items=[]; files_read=0
    old_is_zip=old_archive and ((old_archive.inner.type_name if old_archive.is_split_container and old_archive.inner else old_archive.type_name)=='zip')
    for it in keep_old:
