        if old_is_zip and not it.user_data.get('renamed'):
            # preserved compressed data and metadata
            try:
                packed,local_extra=formats.zip_local_data(old_archive.inner if old_archive.is_split_container else old_archive,it)
            except Exception:
                packed=b''; local_extra=b''
            dost=0; dosd=0
            if it.mtime_dos: 
                y,mo,d,h,mi,s=it.mtime_dos; dost=((h<<11)|((mi&0x3F)<<5)|((s//2)&0x1F)); dosd=(((y-1980)&0x7F)<<9)|((mo&0xF)<<5)|(d&0x1F)
            else:
                dt=util.dos_time_from_unixns(it.mtime_ns); dost=((dt[3]<<11)|((dt[4]&0x3F)<<5)|((dt[5]//2)&0x1F)); dosd=(((dt[0]-1980)&0x7F)<<9)|((dt[1]&0xF)<<5)|(dt[2]&0x1F)
            wi.preserved={'packed':packed,'crc':it.crc or 0,'size':it.size or 0,'method':it.user_data.get('method_id',0),'need':it.version_needed or 10,'flags':it.user_data.get('flags',0),'dost':dost,'dosd':dosd,'ext_attr':it.user_data.get('ext_attr',0),'made_by':it.user_data.get('made_by',63|(3<<8)),'local_extra':local_extra,'central_extra':it.user_data.get('extra',b''),'int_attr':it.user_data.get('int_attr',0),'raw_name':it.user_data.get('raw_name',it.path.encode()),'raw_comment':(it.comment or '').encode()}
            wi.data=b''
        else:
            try: wi.data=b'' if it.is_dir else openarc.get_item_data(old_archive,it,octx.dict())
            except Exception: wi.data=b''
            if it.symlink: wi.data=it.symlink.encode()
        items.append(wi)
    for it in add_new:
        wi=formats.ZipWItem(); wi.path=it.path; wi.is_dir=it.is_dir; wi.mtime_ns=it.mtime_ns; wi.mode=it.mode; wi.attr=it.attr; wi.data=b'' if it.is_dir else read_new_item_data(it,opts)
        if not it.is_dir and len(wi.data)>0: files_read+=1
