        if opts.command is None:
            if not opts.bare: S.out(banner_text()); S.out("\n")
            S.err("\n\nCommand Line Error:\nThe command must be specified\n"); return 7
        if opts.command not in ('a','b','d','e','h','i','l','rn','t','u','x'):
