      'z16':b'\x00'*16,'z8':b'\x00'*8,'empty':b'','Dempty':Dempty,'Dslash':dig(algo,b'/'),'Dname':dig(algo,name.encode()),'Dname16':dig(algo,name.encode('utf-16le')),
