import struct

class RangeDecoder:
    def __init__(self,data):
        self.data=data; self.pos=0; self.range=0xFFFFFFFF; self.code=0
        if len(data)<5: raise ValueError('short')
        b=data[0]; self.pos=1
        # first byte is ignored / must be 0 in normal streams
        for i in range(4): self.code=(self.code<<8)|data[self.pos]; self.pos+=1
    def _norm(self):
        if self.range < (1<<24):
            if self.pos < len(self.data): nb=self.data[self.pos]; self.pos+=1
            else: nb=0
            self.code=((self.code<<8)|nb)&0xFFFFFFFF; self.range=(self.range<<8)&0xFFFFFFFF
    def bit(self, probs, idx):
        prob=probs[idx]; bound=(self.range>>11)*prob
        if self.code < bound:
            self.range=bound; probs[idx]=prob+((2048-prob)>>5); bit=0
        else:
            self.code-=bound; self.range-=bound; probs[idx]=prob-(prob>>5); bit=1
        self._norm(); return bit
    def direct_bits(self,n):
        val=0
        for i in range(n):
            self.range >>= 1
            if self.code >= self.range:
                self.code-=self.range; bit=1
            else: bit=0
            val=(val<<1)|bit; self._norm()
        return val

class RangeEncoder:
    def __init__(self):
        self.out=bytearray(); self.low=0; self.range=0xFFFFFFFF; self.cache=0; self.cache_size=1
    def _shift_low(self):
        if self.low < 0xFF000000 or (self.low>>32):
            temp=self.cache
            while True:
                self.out.append((temp + (self.low>>32)) & 0xFF)
                temp=0xFF
                self.cache_size-=1
                if self.cache_size==0: break
            self.cache=(self.low>>24)&0xFF
        self.cache_size+=1
        self.low=((self.low & 0xFFFFFF) << 8) & 0xFFFFFFFF
    def _norm(self):
        if self.range < (1<<24):
            self.range=(self.range<<8)&0xFFFFFFFF; self._shift_low()
    def bit(self,probs,idx,bit):
        prob=probs[idx]; bound=(self.range>>11)*prob
        if bit==0:
            self.range=bound; probs[idx]=prob+((2048-prob)>>5)
        else:
            self.low+=bound; self.range-=bound; probs[idx]=prob-(prob>>5)
        self._norm()
    def direct_bits(self,val,n):
        for i in range(n-1,-1,-1):
            self.range >>= 1
            if (val>>i)&1: self.low+=self.range
            self._norm()
    def flush(self):
        for i in range(5): self._shift_low()
        return bytes(self.out)

def _new_probs(n): return [1024]*n

class LZMA1Transcoder:
    def __init__(self,data,dict_size=1<<20,lc=3,lp=0,pb=2,spec_offset_mode='base_minus_slot'):
        self.dec=RangeDecoder(data); self.enc=RangeEncoder(); self.spec_offset_mode=spec_offset_mode
        self.lc=lc; self.lp=lp; self.pb=pb; self.num_pos_states=1<<pb
        nps=self.num_pos_states
        def P(n): return [_new_probs(n),_new_probs(n)]
        self.p_is_match=P(12*nps); self.p_is_rep=P(12); self.p_is_rep_g0=P(12); self.p_is_rep_g1=P(12); self.p_is_rep_g2=P(12); self.p_is_rep_long=P(12*nps)
        self.p_pos_slot=P(4*64); self.p_spec=P(256+16); self.p_align=P(16)
        self.len_coder=self._new_len_coder(); self.rep_len_coder=self._new_len_coder()
        lit_count=0x300 * ((1<<lp) << lc) if (lc+lp) else 0x300
        # Actually number of literal contexts = 1 << (lc+lp)
        lit_count=0x300 * (1<<(lc+lp))
        self.p_lits=P(lit_count)
        self.state=0; self.reps=[0,0,0,0]; self.out=bytearray(); self.include_eopm=True
    def _new_len_coder(self):
