        return {'choice':[_new_probs(1),_new_probs(1)],'choice2':[_new_probs(1),_new_probs(1)],'low':[[_new_probs(8) for _ in range(nps)] for __ in range(2)],'mid':[[_new_probs(8) for _ in range(nps)] for __ in range(2)],'high':[_new_probs(256),_new_probs(256)]}
    def bit(self,pair,idx):
        b=self.dec.bit(pair[0],idx); self.enc.bit(pair[1],idx,b); return b
    def bittree(self,pair,n):
