                idx=base+0x100+(mbit<<8)+decoded
                b=self.bit(self.p_lits,idx); decoded=(decoded<<1)|b
                if mbit!=b: break
                if decoded>=0x100: break
            while decoded<0x100:
                b=self.bit(self.p_lits,base+decoded); decoded=(decoded<<1)|b
            byte=decoded&0xFF
        else:
            decoded=1
            while decoded<0x100:
                b=self.bit(self.p_lits,base+decoded); decoded=(decoded<<1)|b
            byte=decoded&0xFF
