        if self.bit(self.p_is_rep,self.state)==1:
            if self.bit(self.p_is_rep_g0,self.state)==0:
                if self.bit(self.p_is_rep_long,(self.state<<self.pb)+pos_state)==0:
                    self.state=9 if self.state<7 else 11
                    self._copy_match(1,self.reps[0]); return False
                dist=self.reps[0]
            else:
