from model import Archive,Item,OpenArchiveError,DataErrorItem
import util

def _read_cstr(data,pos):
    end=data.find(b'\x00',pos)
    if end<0: raise OpenArchiveError('Unexpected end of archive')
    return data[pos:end].decode('utf-8','replace'),end+1

def open_cab(data,path,opts,physical_size=None):
