    try:
        cb_cabinet=struct.unpack_from('<I',data,8)[0]
        coff_files=struct.unpack_from('<I',data,16)[0]
        minor,major=data[24],data[25]
        cfolders,cfiles,flags,setid,icab=struct.unpack_from('<HHHHH',data,26)
        pos=36; hdr_res=0; folder_res=0; data_res=0
        if flags&4:
            hdr_res,folder_res,data_res=struct.unpack_from('<HBB',data,pos); pos+=4
        prev_name=''; next_name=''
        if flags&1:
            prev_name,pos=_read_cstr(data,pos); prev_disk,pos=_read_cstr(data,pos)
        if flags&2:
            next_name,pos=_read_cstr(data,pos); next_disk,pos=_read_cstr(data,pos)
        folders=[]
