            # archival bits map to mode? if execute bit 0x40 set mode rwx?
            it.user_data.update({'folder':ifolder,'off':offfolder,'attribs':attribs})
            items.append(it)
    except OpenArchiveError: raise
    except Exception:
        raise OpenArchiveError('Headers Error')
    archive=Archive(); archive.path=path; archive.type_name='Cab'; archive.data=data; archive.physical_size=physical_size if physical_size is not None else len(data); archive.items=items
    # methods
    method_names=[]
    for f in folders:
        mn=_method_name(f['type'])
        # assign to items
        if mn not in method_names: method_names.append(mn)
    for it in items:
        fi=it.user_data.get('folder')
        it.method=_method_name(folders[fi]['type']) if isinstance(fi,int) and fi < len(folders) else (method_names[0] if method_names else 'None')
        # attributes for SLT: format_attributes with attr; but if attr has no 0x8000, fine.
    archive._cab_folders=folders
    archive.props=[('Physical Size',str(archive.physical_size)),('Method',' '.join(method_names)),('Blocks',str(len(folders))),('Volumes','1'),('Volume Index',str(icab)),('ID',str(setid))]
    archive.total_compressed_override=archive.physical_size
    return archive

def _dos_tuple(d,t):
    sec=(t&31)*2; minute=(t>>5)&63; hour=(t>>11)&31; day=d&31; mon=(d>>5)&15; year=((d>>9)&127)+1980
    if mon==0: mon=1
